/* DAWAH X — ahmad, অধ্যায় 122 · খণ্ড 122 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][122]=[[24201,24201,"","আমরা সেই বুড়ো লোকটির কথা বলেছিলাম যে আমাদের সব থেকে ভালো মানুষ খুঁজতে বলেছে, সে বলেছিল, ভাববাদী তার কাছে প্রার্থনা করছে আর যদি সে তার দুর্দশা থেকে সরে যায় তাহলে সে আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ مِنْ مُغْتَسَلِهِ حَيْثُ يَغْتَسِلُ مِنْ الْجَنَابَةِ يَغْسِلُ قَدَمَيْهِ ‏","","",""],[24202,24202,"","আমরা এক ভিন্ন স্বপ্নের কথা বলেছি, যার মধ্যে বাস করার জন্য তিনি বলেছিলেন যে ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন। পরিহাস হচ্ছে, এই গানটি ছিল নিয়ন্ত্রণ করা এবং গান ব্যবহার করা যেত।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَكَانُ الْكَيِّ التَّكْمِيدُ وَمَكَانُ ‏ ‏الْعِلَاقِ ‏ ‏السَّعُوطُ ‏ ‏وَمَكَانُ النَّفْخِ ‏ ‏اللَّدُودُ ‏","","",""],[24203,24203,"","শেষ বার আমরা কথা বলেছিলাম, কেন সে জন্মগ্রহণ করেছে, সে ঐ পূর্বনির্ধারিত লোকদের হাতে পৌঁছে দিবে, লাইনে আটকে যাবে, সে চলে যাবে, ঈশ্বর আমার ছেলেদের অন্ধকার থেকে একটি গোপন বিষয়, যেটা দুনিয়ার সবচেয়ে খারাপ ছিল, সেটা আমি বুঝতে পারছি, তারা কে বা কে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمَّا أَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏بَدْرٍ ‏ ‏بِأُولَئِكَ ‏ ‏الرَّهْطِ ‏ ‏فَأُلْقُوا فِي ‏ ‏الطُّوَى ‏ ‏عُتْبَةُ ‏ ‏وَأَبُو جَهْلٍ ‏ ‏وَأَصْحَابُهُ وَقَفَ عَلَيْهِمْ فَقَالَ ‏ ‏جَزَاكُمْ اللَّهُ شَرًّا مِنْ قَوْمِ نَبِيٍّ مَا كَانَ أَسْوَأَ الطَّرْدِ وَأَشَدَّ التَّكْذِيبِ قَالُوا يَا رَسُولَ اللَّهِ كَيْفَ تُكَلِّمُ قَوْمًا ‏ ‏جَيَّفُوا ‏ ‏فَقَالَ مَا أَنْتُمْ ‏ ‏بِأَفْهَمَ لِقَوْلِي مِنْهُمْ ‏ ‏أَوْ لَهُمْ أَفْهَمُ لِقَوْلِي مِنْكُمْ ‏","","",""],[24204,24204,"","আমরা বলতে চাই, ঈশ্বর তার সাথে এমন কিছু করেছেন, তার নিজের বিশ্বাস আর তার প্রয়োজন তার বেঁচে থাকার জন্য আর তার কোন উপায় নেই। বেঁচে থাকতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُفْرِغُ يَمِينَهُ لِمَطْعَمِهِ وَلِحَاجَتِهِ وَيُفْرِغُ شِمَالَهُ ‏ ‏لِلِاسْتِنْجَاءِ وَلِمَا هُنَاكَ ‏","","",""],[24205,24205,"","আমরা শমকে বলেছিলাম যে, আমরা তাকে তার গ্রেসের প্রতি ঈর্ষা করি ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَغْسِلُ رَأْسَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهِيَ حَائِضٌ وَهُوَ مُعْتَكِفٌ يُخْرِجُ رَأْسَهُ مِنْ الْمَسْجِدِ إِلَى الْحُجْرَةِ ‏","","",""],[24206,24206,"","আমরা একটা বাসা সম্পর্কে তাদের মন পরিবর্তন করার কথা বলেছি আর আমরা বেঁচে আছি, ঈশ্বর তাঁর পক্ষে পৌঁছে দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُغِيرَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَتَّزِرُ وَأَنَا حَائِضٌ فَأَدْخُلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحَافَهُ ‏","","",""],[24207,24207,"","আমরা একটা জীবন নিয়ে কথা বলেছিলাম যেটা হয়তো খুঁজে পেতে চেষ্টা করেছিল, সে তার সিদ্ধান্ত নিয়ে গেছে, সে তালাক হিসেবে গণনা করেনি।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُغِيرَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدْ ‏ ‏خَيَّرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاخْتَرْنَاهُ فَلَمْ يَعُدَّ ذَلِكَ طَلَاقًا ‏","","",""],[24208,24208,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি ঘুমিয়েছিলেন এবং তিনি একজন কাপুরুষ ছিলেন । কে কখনো পানি স্পর্শ করবে না।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ بْنِ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُ وَهُوَ جُنُبٌ وَلَا يَمَسُّ مَاءً ‏","","",""],[24209,24209,"","আমরা আবেগ নিয়ে কথা বলেছি, আমরা খুশি হয়েছি, তারা তোমাকে বিয়ে করতে যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مُرُوا أَزْوَاجَكُنَّ ‏ ‏أَنْ يَغْسِلُوا عَنْهُمْ أَثَرَ ‏ ‏الْغَائِطِ ‏ ‏وَالْبَوْلِ فَإِنِّي ‏ ‏أَسْتَحْيِيهِمْ وَإِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَفْعَلُهُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏مُرْنَ أَزْوَاجَكُنَّ ‏","","",""],[24210,24210,"","আমরা কিছু স্নায়ুকে দিয়ে দিয়েছি যা আমরা পরে খুশির সাথে করেছি। কালো লোকটি বলেছিল, সে এটা উদ্ধার করতে হবে। এমনকি তার হাত দিয়ে তাকে রক্ষা করলেও তার সাথে লড়াই করা উচিত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَرَادَ أَنْ يَغْتَسِلَ بَدَأَ بِكَفَّيْهِ فَغَسَلَهُمَا ثُمَّ أَفَاضَ بِيَمِينِهِ عَلَى شِمَالِهِ فَغَسَلَ مَرَاقَّهُ حَتَّى إِذَا أَنْقَى أَهْوَى بِيَدِهِ إِلَى الْحَائِطِ ثُمَّ غَسَلَهَا ثُمَّ اسْتَقْبَلَ الطَّهُورَ وَأَفَاضَ عَلَيْهِ الْمَاءَ ‏","","",""],[24211,24211,"","আমরা এই কামনায় বাপ্তাইজিত হয়েছি যে আমরা সুখী হতে এবং প্রতিশ্রুতি নিয়ে সুখী হতে পেরে খুশি হতে পেরে খুশি হয়েছি। ডানা থেকে উদ্ধার করো.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ الْعَدَوِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24212,24212,"","আমি যা বলেছি, আমার বাবার একটা স্বপ্ন আছে। আর ঈশ্বরের অনুগ্রহে তাঁর ইচ্ছা আছে আর একপাশের গেট থেকে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24213,24213,"","আমরা আবেগে বাপ্তাইজিত হয়েছি, আমরা আমার বাবা বিয়ে করা নিয়ে খুশি যে সে খুন করার চেষ্টা করছে। ঈশ্বর আদেশ দিয়েছেন, ঈশ্বর তাকে তার প্রার্থনার কাছে সমর্পণ করবেন। গর্ব আর আনন্দ, সিঁড়ির মত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏بُدَيْلٍ ‏ ‏عَنْ ‏ ‏أَبِي الْجَوْزَاءِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَفْتَتِحُ صَلَاتَهُ بِالتَّكْبِيرِ وَيَفْتَتِحُ الْقِرَاءَةَ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏وَيَخْتِمُهَا بِالتَّسْلِيمِ ‏","","",""],[24214,24214,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের জন্য একটা দশম বিবাহ অনুষ্ঠানের মাধ্যমে খুশি করেছে। আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার জন্য এবং খুনের জন্য আমার অনুসন্ধানের পথ অনুসরণ করব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنِ ‏ ‏النَّخَعِيِّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْعَثُ بِالْهَدْيِ فَنَفْتِلُ لَهَا قَلَائِدَهَا ثُمَّ لَا يُمْسِكُ عَنْ شَيْءٍ مِمَّا يُمْسِكُ عَنْهُ الْمُحْرِمُ ‏","","",""],[24215,24215,"","আমরা একটা বিশেষ আবেগ নিয়ে কথা বলেছি যা আমরা তৈরি করেছি, আর সে করেছে, সে শেষ করেছে, আমি যা বলি, তুমি আমাকে ক্ষমা করো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ بُرَيْدَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا نَبِيَّ اللَّهِ أَرَأَيْتَ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ مَا أَقُولُ قَالَ تَقُولِينَ ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24216,24216,"","আমরা একজন ভালো মানুষ হিসেবে যে আবেগে আমরা যা করেছি তা হল ঈশ্বর একটা কুকুরের ছেলে, যে তাকে জীবিত বলতে বলেছিল তার জন্য আর আমি প্রার্থনা করবো আলোর জন্য। আমি বলেছিলাম যে, এটা গারসিয়াস নামের এক ব্যক্তি বলেছে যে তার লোকেরা ধ্বংস হয়ে যাওয়ার পর সে বলেছে যে, তিনি দেওয়াল ধ্বংস করার সিদ্ধান্ত নেবেন। আমি বলেছি, এটা ছিল সারা মাস ধরে আমার কাজ। আমি বলেছিলাম, আমি যদি বলি, এটা একটা নতুন করে শুরু করেছি, তবে আমি এটা করতে পারি। আমি মনে করি, আমি জানি, এটা একটা নতুন জিনিস। আমি জানি, আমি যদি আমার জীবনের জন্য একটা জিনিস খুঁজে পাই, তাহলে আমি এটা একটা নতুন জিনিস। আমি মনে করি, আমি জানি, আমি যদি এটা একটা জিনিসও করি, আমি এটা একটা ছোট জিনিস। আমি জানি, আমি জানি, আমি জানি, আমি জানি, আমি কি করতে পারি। আমি জানি, আমি জানি, আমি কি করেছি। আমি যা করি তা শিখে গেছি। তাকে খুঁজে বের করতে তিনি কৃতজ্ঞ হবেন এবং আপনি যেভাবে বলেছেন আমার বাবা হয়তো বেঁচে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏كَهْمَسٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ الْمُقْرِيُّ ‏ ‏عَنْ ‏ ‏كَهْمَسٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ شَقِيقٍ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏أَكَانَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ الضُّحَى قَالَتْ لَا إِلَّا أَنْ يَجِيءَ مِنْ ‏ ‏مَغِيبَةٍ ‏ ‏قَالَ قُلْتُ أَكَانَ ‏ ‏يُصَلِّي جَالِسًا قَالَتْ بَعْدَمَا حَطَمَهُ النَّاسُ قَالَ قُلْتُ أَكَانَ يَقْرَأُ السُّورَةَ فَقَالَتْ ‏ ‏الْمُفَصَّلَ ‏ ‏قَالَ قُلْتُ أَكَانَ يَصُومُ شَهْرًا كُلَّهُ قَالَتْ مَا عَلِمْتُهُ صَامَ شَهْرًا كُلَّهُ إِلَّا رَمَضَانَ وَلَا أَعْلَمُهُ أَفْطَرَ شَهْرًا كُلَّهُ حَتَّى يُصِيبَ مِنْهُ حَتَّى مَضَى لِوَجْهِهِ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏يَقْرِنُ ‏ ‏وَكَذَلِكَ قَالَ ‏ ‏أَبُو عَبْدِ الرَّحْمَنِ ‏","","",""],[24217,24217,"","আমরা আমাদের আবেগকে সেরে ফেলার চেষ্টা করেছি একটি রীতিতে যা আমরা শুনেছি খারাপ ছেলে যে তাকে খুজে পাওয়া গেছে। এমন কিছু হতে যাচ্ছে যেটা সে বুঝতে পারছে না.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمِقْدَامَ بْنَ شُرَيْحِ بْنِ هَانِىءٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏رَكِبَتْ ‏ ‏عَائِشَةُ ‏ ‏بَعِيرًا وَكَانَ مِنْهُ صُعُوبَةٌ فَجَعَلَتْ تُرَدِّدُهُ فَقَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكِ بِالرِّفْقِ فَإِنَّهُ لَا يَكُ فِي شَيْءٍ إِلَّا زَانَهُ وَلَا يُنْزَعُ مِنْ شَيْءٍ إِلَّا شَانَهُ ‏","","",""],[24218,24218,"","আমরা এক বছর আবেগ নিয়ে কথা বলেছি যে জীবনের এক বছর কথা আমি তার জন্য প্রার্থনা করেছি এবং একদিন থেকে আমাকে আত্মসমর্পণ করতে হবে তাকে ফিরিয়ে দাও.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ فَيُبَادِرُنِي وَأُبَادِرُهُ حَتَّى ‏ ‏أَقُولَ دَعْ لِي دَعْ لِي ‏","","",""],[24219,24219,"","আমরা যে আবেগ নিয়ে কথা বলেছি তা আমাদের একজন নারীর জীবনের সন্দেহ বাড়িয়ে দিয়েছে, ঈশ্বরের ইচ্ছা তার কাছে প্রার্থনা করবে এবং আমরা যা করি, তা হলো আলো যা ঈশ্বর করেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏هَلْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَ قَالَتْ نَعَمْ وَيُزِيدُ مَا شَاءَ اللَّهُ ‏","","",""],[24220,24220,"","আমরা যে আবেগ নিয়ে বড় হয়েছি তা হলো খারাপের সন্দেহ বেড়ে যাওয়া। গেটে বলা হয়েছে, পানি আমার হয়তো কোন কিছু থেকে বেঁচে যাবে না। তিনি তার হাত ধরে আছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏قَالَتْ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَتْ ‏ ‏إِنَّ الْمَاءَ لَا يُنَجِّسُهُ شَيْءٌ قَدْ كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ يَبْدَأُ فَيَغْسِلُ يَدَيْهِ ‏","","",""],[24221,24221,"","আমরা একটা রীতি আর একটা চাহিদা তৈরি করেছি যেটা আমাকে তার ভালবাসার প্রতি আবেগ দেখাতে সাহায্য করেছে। আমি বলেছিলাম, \"এমিনেন্টের মা\" ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে । ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে ঈশ্বরের কাছে । ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে, ঈশ্বরের কাছে প্রার্থনা করতে, ঈশ্বরের কাছে প্রার্থনা করতে হবে, যেন তিনি তাঁর কাছে বই এবং দুঃখ এবং মিথ্যা বিশ্বের কাছে তুলে ধরতে পারেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏يَا أُمَّ الْمُؤْمِنِينَ أَخْبِرِينِي عَمَّا نَهَى عَنْهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْأَوْعِيَةِ قَالَتْ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[24222,24222,"","আমরা আবেগ-অনুভূতি নিয়ে কথা বলেছি এবং আমাকে বলা দরকার, যেন ইশ্বরের প্রতি দয়া আর ঈশ্বরের প্রেমের মধ্যে করুণা আর করুণা সম্পর্কে কথা বলা। আমি এমন একজন মহিলাকে গ্রহণ করছি যাকে কথা বলতে বলা হবে। ঈশ্বরের দয়ায় আর তাঁর কাছে এটা বলে যে তিনি দেবতা। আজ সন্ধ্যাটা ততোধিক গরম হয়ে যাবে আর দুষ্টরা একে মুছে যাবে আর সূর্য হারিয়ে যাবে। সে একা একা ধুতে থাকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ امْرَأَةً مُسْتَحَاضَةً سَأَلَتْ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقِيلَ إِنَّمَا هُوَ ‏ ‏عِرْقٌ ‏ ‏عَانِدٌ ‏ ‏وَأُمِرَتْ أَنْ تُؤَخِّرَ الظُّهْرَ وَتُعَجِّلَ الْعَصْرَ وَتَغْتَسِلَ غُسْلًا وَاحِدًا وَتُؤَخِّرَ الْمَغْرِبَ وَتُعَجِّلَ الْعِشَاءَ وَتَغْتَسِلَ لَهُمَا غُسْلًا وَاحِدًا وَتَغْتَسِلَ لِصَلَاةِ الصُّبْحِ غُسْلًا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏غُسْلًا وَاحِدًا ‏","","",""],[24223,24223,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা আমাদের এক সাথে এক আকাঙ্ক্ষা তৈরি করেছে যা একটি ক্র্যাডেল তৈরি করেছে যা ক্ষমার আঙ্গুর সৃষ্টি করেছে। যাজকের কথা শুনে... ...তিনি বলেছিলেন, প্রভুর আদেশতে তৃতীয় জন আছে, তার কাছে একটা মই আছে তাকে বলতে যে, আমি তাকে যেতে দেব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كَانَ لَهَا ثَوْبٌ فِيهِ تَصَاوِيرٌ مَمْدُودٌ إِلَى ‏ ‏سَهْوَةٍ ‏ ‏وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي إِلَيْهَا فَقَالَ أَخِّرِيهِ عَنِّي قَالَتْ فَأَخَّرْتُهُ فَجَعَلْتُهُ وَسَائِدَ ‏","","",""],[24224,24224,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের একসাথে এনেছে সূর্যের অনুগ্রহের কথা শুনতে। সে বিয়ার খেতে চায় তার গলা চেপে ধরে। সে বলল, আমি এটা কিনতে চাই এবং আমি ঘৃণা করি, কিন্তু ঈশ্বর এসে হাজির হয়েছেন। ঈশ্বর তাকে আদেশ দিয়েছেন এবং তিনি তাকে হত্যা করার জন্য তাঁর ওপর বিশ্বাস রেখে এই বিশ্বাস রেখে যে, তাঁকে হত্যা করার তার এক বন্ধুত্ব আছে এবং তাকে হত্যা করার ক্ষমতা তাঁর আছে । আমি তাকে বিয়ে করতে বলবো আর বলবো আমি জানি না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ الْقَاسِمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏أَرَادَتْ أَنْ تَشْتَرِيَ ‏ ‏بَرِيرَةَ ‏ ‏لِلْعِتْقِ فَاشْتَرَطُوا ‏ ‏وَلَاءَهَا ‏ ‏فَذَكَرَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اشْتَرِيهَا وَأَعْتِقِيهَا فَإِنَّ ‏ ‏الْوَلَاءَ ‏ ‏لِمَنْ أَعْتَقَ وَأُهْدِيَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَحْمٌ فَقَالُوا لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا مَا تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ وَخُيِّرَتْ ‏ ‏فَقَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَكَانَ زَوْجُهَا حُرًّا ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ عَنْ زَوْجِهَا فَقَالَ لَا أَدْرِي ‏","","",""],[24225,24225,"","আমরা একটা ঈর্ষাপরায়ণ চুইংগাম বানিয়েছি, যা আমাদের প্রয়োজনের মধ্যে নিয়ে এসেছে এবং আমাকে সবচেয়ে ভালো কিছু খুঁজতে চেষ্টা করছে। আমার বাবা বলেছেন, আমি ঈশ্বরের দোহাইর কাছে ভিক্ষা চাইছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَغْتَسِلُ أَنَا وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ مِنْ الْجَنَابَةِ ‏","","",""],[24226,24226,"","আমি বলেছিলাম, সে তার আদর্শ নিয়ে বাইরে বের হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏أَبِي مَعْشَرٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ النَّخَعِيِّ ‏ ‏أَنَّهُ ‏ ‏كَانَ يَدْخُلُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏قَالَ قُلْتُ وَكَيْفَ كَانَ يَدْخُلُ عَلَيْهَا قَالَ كَانَ يَخْرُجُ مَعَ خَالِهِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ وَكَانَ بَيْنَهُ وَبَيْنَ ‏ ‏عَائِشَةَ ‏ ‏إِخَاءٌ وَوُدٌّ ‏","","",""],[24227,24227,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা আমাদের কাছে বাস্তবের জন্য অপরিহার্যতার জন্য পূর্বনির্ধারিত। আমি কখনোই বলিনি এটা ঈশ্বরের কাছে যাবে, এটা তোমার কাছে পৌঁছে দিতে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَبْدِ الرَّحْمَنِ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا طَلَعَ الْفَجْرُ صَلَّى رَكْعَتَيْنِ ‏ ‏أَوْ لَمْ يُصَلِّ إِلَّا رَكْعَتَيْنِ ‏ ‏أَقُولُ يَقْرَأُ فِيهِمَا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏","","",""],[24228,24228,"","আমরা আবেগ-অনুভূতি নিয়ে কথা বলেছি এবং প্রয়োজনের কথা বলেছি আমরা আপনার টাকা একটি স্ট্রিপার পরিকল্পনা থেকে পেয়েছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং ডাক্তার এবং ডাক্তার এবং আত্মসমর্পণ করেছেন। দুঃখ আর পৃথিবী ভুয়া।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ عُرْفُطَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ خَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْحَنْتَمِ ‏ ‏وَالْمُزَفَّتِ ‏","","",""],[24229,24229,"","আমরা আবেগ নিয়ে কথা বলেছি যা বাবার জীবনের রীতি তৈরী করেছি। আমি কখনোই কারো ক্ষুধাকে তার জন্য প্রার্থনা করতে দেখিনি এবং শান্তির জন্য প্রার্থনা করতে চেয়েছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا رَأَيْتُ الْوَجَعَ عَلَى أَحَدٍ أَشَدَّ مِنْهُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24230,24230,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদেরকে প্রভুর মৃত্যুর মুখ বহন করতে সাহায্য করেছে। তিনি বলেছিলেন যে, তিনি প্রভুর কাছে প্রার্থনা করছেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَيْثَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏قَالَ قُلْنَا ‏ ‏لِعَائِشَةَ ‏ ‏إِنَّ فِينَا رَجُلَيْنِ مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَدُهُمَا يُعَجِّلُ الْإِفْطَارَ وَيُؤَخِّرُ السُّحُورَ وَالْآخَرُ يُؤَخِّرُ الْإِفْطَارَ وَيُعَجِّلُ السُّحُورَ قَالَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَيُّهُمَا الَّذِي يُعَجِّلُ الْإِفْطَارَ وَيُؤَخِّرُ السُّحُورَ قَالَ فَقُلْتُ هُوَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏فَقَالَتْ كَذَا كَانَ يَصْنَعُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24231,24231,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা কিনা এক দুঃখকষ্টের জীবন নিয়ে এসেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏عُمَارَةَ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏وَلَدُ الرَّجُلِ مِنْ كَسْبِهِ مِنْ أَطْيَبِ كَسْبِهِ ‏","","",""],[24232,24232,"","আমরা আমাদের ভাই-বোনের মৃত্যুর জন্য আমাদের জন্য একটি আবেগ কথা বলেছি, তিনি বলেছিলেন, এটা ঈশ্বরের কাছে প্রার্থনা করা এবং তার নারীদের প্রাণ দান করা ভালো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الضُّحَى ‏ ‏يُحَدِّثُ عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَدْ خَيَّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نِسَاءَهُ أَفَكَانَ طَلَاقًا ‏","","",""],[24233,24233,"","আমরা এক বছর আগে যে আবেগ নিয়ে কথা বলেছি, সে বলল সে নাকি ঈশ্বরের সর্বোচ্চ মঙ্গল দেখেছে এবং সে তার উদ্ধার করেছে এবং সে অবিশ্বাস্য অবস্থা থেকে মুক্ত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَقَدْ رَأَيْتُ ‏ ‏وَبِيصَ ‏ ‏الطِّيبِ ‏ ‏فِي رَأْسِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[24234,24234,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা আমাদের কাছে জীবন্তদের দেখানোর জন্য একটা ইচ্ছা বহন করতে সাহায্য করেছে। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি সিঁড়ি থেকে আত্মসমর্পণ করেছেন যার কোন কিছু করার নেই। তার শান্তির সাথে, ভুল।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ مُسْلِمٍ يُشَاكُ شَوْكَةً فَمَا فَوْقَهَا إِلَّا رَفَعَهُ اللَّهُ بِهَا دَرَجَةً وَحَطَّ عَنْهُ بِهَا خَطِيئَةً ‏","","",""],[24235,24235,"","আমরা এক প্রবল আবেগে বাপ্তাইজিত হয়েছি, যা আমাদের মাঝে মাঝে খেলার জন্য নিয়ে এসেছে, আমি শপথের গোলামের সাথে বাস করি যে সে কখনোই এটা করেনি। সে আমাকে বলেছে, সে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏وَعَبْدِ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏الْمَعْنَى ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏ثَابِتِ بْنِ عُبَيْدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ فَقُلْتُ إِنِّي حَائِضٌ فَقَالَ إِنَّهَا لَيْسَتْ فِي يَدِكِ فَنَاوَلْتُهُ ‏","","",""],[24236,24236,"","আমরা আমাদের জন্য জোর করে ফুলটা গুটিয়ে বলতে চাই আর ঈশ্বর তাকে উদ্ধার করেছেন এবং একটি আলো থেকে উদ্ধার করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏أَخْبَرَنَا ‏ ‏الزُّهْرِيُّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏كَانَتْ تَغْتَسِلُ هِيَ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ إِنَاءٍ وَاحِدٍ ‏","","",""],[24237,24237,"","আমরা খালি পায়ে হেঁটে কিছু বিষের কথা বলেছি, কিভাবে এটা খুঁজে পেতে হবে, হিংসার ব্যাপার হচ্ছে আগুন দিয়ে চলে যাওয়া জীবন নিয়ে, আর এটা দেয়া হয়েছে ঈশ্বর হয়তো দশম আজ্ঞার ভাই, এরপর তিনি তার মুখ এমনকি তার নিজের মুখ পর্যন্ত দেওয়ার আগেই তাঁকে তাঁর ভাই হতে দেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مَيْمُونَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا الْأَحْوَصِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عُرْوَةَ بْنِ الْمُغِيرَةِ بْنِ شُعْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَجُلًا مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ذُكِرَ رَجُلٌ عِنْدَهُ ‏ ‏فَقَالَ ‏ ‏بِئْسَ ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَأَخُو الْعَشِيرَةِ ثُمَّ دَخَلَ عَلَيْهِ فَأَقْبَلَ عَلَيْهِ بِوَجْهِهِ حَتَّى ظَنَنَّا أَنَّ لَهُ عِنْدَهُ مَنْزِلَةً ‏","","",""],[24238,24238,"","আমরা আবেগ নিয়ে কথা বলেছি এবং প্রয়োজনের কথা বলছি যে আমি কাকে খুঁজছি। তিনি যুক্তি দেখিয়েছিলেন যে, আমরা যখন তাকে ছেড়ে যাব, তখন তিনি তাকে ছেড়ে দেবেন । আমার বাবা একটা বাসা থেকে ঈশ্বরের কাছে প্রার্থনা করতে শুনেছিলেন এবং ঈশ্বরের কাছে সাহায্য চেয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَالَ ‏ ‏دَخَلَ نِسْوَةٌ مِنْ أَهْلِ ‏ ‏الشَّامِ ‏ ‏عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ أَنْتُنَّ اللَّاتِي تَدْخُلْنَ الْحَمَّامَاتِ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ امْرَأَةٍ وَضَعَتْ ثِيَابَهَا فِي غَيْرِ بَيْتِهَا إِلَّا هَتَكَتْ سِتْرًا بَيْنَهَا وَبَيْنَ اللَّهِ عَزَّ وَجَلَّ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏إِلَّا هَتَكَتْ سِتْرَهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَبِي الْمَلِيحِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏","","",""],[24239,24239,"","আমরা একটা মূল্য দিতে শুনেছি... ...যাতে আমরা একটা স্বপ্নের কথা শুনেছি... ...তাকে জিজ্ঞেস করলাম যে, ঈশ্বর তাকে যেভাবে বললেন তার কাছে তার কাছে দ্বিতীয়টা আছে, তারপর সে তাকে বলবে যে তার কাছে আছে। তার ডান হাত উড়িয়ে তাকে জিততে হবে, তার তৃতীয় হাত আছে, তারপর সে তার দেহের গোপন তথ্য মুছে ফেলছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا سَلَمَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلْتُهَا عَنْ غُسْلِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْجَنَابَةِ قَالَتْ كَانَ ‏ ‏يُؤْتَى بِإِنَائِهِ فَيَغْسِلُ يَدَيْهِ ثَلَاثًا ثُمَّ يَصُبُّ مِنْ الْإِنَاءِ عَلَى فَرْجِهِ فَيَغْسِلُهُ ثُمَّ يُفْرِغُ بِيَدِهِ الْيُمْنَى عَلَى الْيُسْرَى فَيَغْسِلُهَا ثُمَّ يُمَضْمِضُ وَيَسْتَنْشِقُ ثُمَّ يُفْرِغُ عَلَى ‏ ‏رَأْسِهِ ثَلَاثًا ثُمَّ يَغْسِلُ سَائِرَ جَسَدِهِ ‏","","",""],[24240,24240,"","তিনি বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করছেন আর পরের বার যদি তিনি তার সাথে লড়াই করতে চান, তাহলে তিনি আমাদের আদেশ দেবেন। সে এটা কেনার পর বললো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُ إِحْدَانَا إِذَا حَاضَتْ ‏ ‏فَتَتَّزِرُ ‏ ‏ثُمَّ يُضَاجِعُهَا ‏ ‏قَالَ ‏ ‏هَذَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏ثُمَّ قَالَ بَعْدُ ‏ ‏ثُمَّ ‏ ‏يُبَاشِرُهَا ‏","","",""],[24241,24241,"","আমরা এমন আবেগ নিয়ে কথা বলেছি যা আমাদের অতীতকে বিকৃত করে দিয়েছে। আমি ঈশ্বরের অনুগ্রহের লর্ডকে হত্যা করেছি, ঈশ্বর তাকে উদ্ধার করেছেন এবং তাকে উদ্ধার করেছেন। কিছু করা হবে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَمًا ثُمَّ لَا يَحْرُمُ مِنْهُ شَيْءٌ ‏","","",""],[24242,24242,"","আমরা আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা একটা দাঙ্গা করেছি যেটা আমাদের বলা হয়েছে তার নিজের একটা দৃষ্টি সম্পর্কে। একটা বাসাকে আমি ঈশ্বরের কাছে উৎসর্গ করতে যাচ্ছি, আমার স্বপ্নের মধ্যে দিয়ে। আমি এটা শেষ করতে যাচ্ছি। আমি এটা আমার স্বপ্নের মধ্যে দিয়ে। আমি কি করবো? আমি জানি, আমি কি করতে পারি? বেনের কাছে জিজ্ঞেস করা উচিৎ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَكُونُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَإِذَا أَرَدْتُ أَنْ أَقُومَ كَرِهْتُ أَنْ أَمُرَّ بَيْنَ يَدَيْهِ ‏ ‏فَأَنْسَلُّ ‏ ‏انْسِلَالًا ‏","","",""],[24243,24243,"","আমরা একটা কামনার কথা বলেছি, যে কে এটা দেখেছে, কারণ প্রভুর প্রার্থনা, ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে অনেক আগেই আত্মসমর্পণ করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ كَانَتْ ‏ ‏دِيمَةً ‏","","",""],[24244,24244,"","আমরা আমাদের আবেগ-অনুভূতি দিয়ে চেষ্টা করেছি... ...আমাদের বলতে যে কিভাবে যুদ্ধ করতে হয়.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُبَاشِرُ ‏ ‏وَهُوَ صَائِمٌ ‏","","",""],[24245,24245,"","আমরা একটা আবেগ দ্বারা বাপ্তাইজিত হয়েছি... ...যে আমাদের কাছে একটা সাপের জন্য একটা টোপ নিয়ে এসেছে, স্বপ্নের ছেলের জন্য, তোমার মুখে এটা বেঁচে থাকবে, বাবাকে বলা হয়েছিল, প্রভু, সে আমার স্বপ্নে প্রবেশ করবে এবং সে একজন বীর হবে। সে ঈশ্বরের কাছে প্রার্থনা করবে এবং সে আপনাকে প্রবেশ না করা পর্যন্ত আমি তাকে তার কাছে পৌঁছে দেব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ نَافِعٍ ‏ ‏عَنْ ‏ ‏زَيْنَبَ بِنْتِ أُمِّ سَلَمَةَ ‏ ‏قَالَتْ ‏ ‏أُمُّ سَلَمَةَ ‏ ‏لِعَائِشَةَ ‏ ‏إِنَّهُ يَدْخُلُ عَلَيْكِ الْغُلَامُ ‏ ‏الْأَيْفَعُ ‏ ‏الَّذِي مَا أُحِبُّ أَنْ يَدْخُلَ عَلَيَّ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏أَمَا لَكِ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ قَالَتْ ‏ ‏إِنَّ ‏ ‏امْرَأَةَ أَبِي حُذَيْفَةَ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏سَالِمًا ‏ ‏يَدْخُلُ عَلَيَّ وَهُوَ رَجُلٌ وَفِي نَفْسِ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏مِنْهُ شَيْءٌ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْضِعِيهِ حَتَّى يَدْخُلَ عَلَيْكِ ‏","","",""],[24246,24246,"","আমরা আমাদের আবেগকে সেরে ফেলার চেষ্টা করেছি, যা আমাদের বাবার ভালোবাসাকে জাগিয়ে তুলেছে। আমাদের মধ্যে যারা পরাজিত হয়েছিল... ...তারপর তাকে হত্যা করা হয়.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْروِ بْنِ شُرَحْبِيلَ ‏ ‏عَنْ ‏ ‏أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْمُرُنَا إِذَا كَانَتْ إِحْدَانَا حَائِضًا أَنْ ‏ ‏تَتَّزِرَ ‏ ‏ثُمَّ تَدْخُلَ مَعَهُ فِي لِحَافِهِ ‏","","",""],[24247,24247,"","আমরা বাবার সাথে কথা বলেছি, সে ঈশ্বরের কাছে প্রার্থনা করেনি আর সে একটা দড়ির সাথে লড়াই করবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي عَبْدِ اللَّهِ الْجَدَلِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمْ يَكُنْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَاحِشًا ‏ ‏وَلَا ‏ ‏مُتَفَحِّشًا ‏ ‏وَلَا صَخَّابًا فِي الْأَسْوَاقِ وَلَا ‏ ‏يُجْزِي بِالسَّيِّئَةِ مِثْلَهَا وَلَكِنْ يَعْفُو وَيَصْفَحُ ‏","","",""],[24248,24248,"","আমরা আবেগ-অনুভূতি দিয়ে এটা করতে চেষ্টা করেছি যে যখন আমি কথা বলছি তখন আমরা কথা বলেছি। এটা এমন হবে যে তিনি তার নিজের ছেলেকে খুঁজে পাবার চেষ্টা করছেন। আমার বাবা নিজের জীবনের জন্য তাকে যেতে বলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ بْنُ سُلَيْمٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَاهُ ‏ ‏يُحَدِّثُ ‏ ‏وَقَالَ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَيْهَا وَعِنْدَهَا رَجُلٌ فَكَأَنَّهُ غَضِبَ فَقَالَتْ إِنَّهُ أَخِي قَالَ ‏ ‏انْظُرْنَ مَا إِخْوَانُكُنَّ فَإِنَّمَا الرَّضَاعَةُ مِنْ الْمَجَاعَةِ ‏","","",""],[24249,24249,"","আমরা একটা আবেগ নিয়ে কথা বলেছি, যা আমাদের একটা মেয়েকে খুঁজে বের করার জন্য একটা সমস্যায় ফেলেছে, প্রভু তাকে ভিতরে ঢুকিয়েছেন, স্বামীর শাস্তি হিসেবে তাকে যেতে হবে। সে ঠিক কাজ করার আগেই কবর দিয়ে যেতে হলে, তার জন্য প্রার্থনা করতে হয়।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَشْعَثِ بْنِ سُلَيْمٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ يَهُودِيَّةً دَخَلَتْ عَلَيْهَا فَذَكَرَتْ عَذَابَ الْقَبْرِ فَقَالَتْ لَهَا أَعَاذَكِ اللَّهُ مِنْ عَذَابِ الْقَبْرِ فَسَأَلَتْ ‏ ‏عَائِشَةُ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَذَابِ الْقَبْرِ فَقَالَ نَعَمْ ‏ ‏عَذَابُ الْقَبْرِ حَقٌّ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَمَا رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةً بَعْدُ إِلَّا تَعَوَّذَ مِنْ عَذَابِ الْقَبْرِ ‏","","",""],[24250,24250,"","আমি কামনা এবং আনন্দের সাথে কথা বলেছি এবং চেষ্টা করেছি। আমার কাছে সবচেয়ে ভাল একজন সাক্ষী যিনি বলেছিলেন যে তিনি ছিলেন একজন ছেলে এবং তিনি ছিলেন একজন সাক্ষী। এবং তারপর আমার কাছে আমার কাছে ভালো একটি সাক্ষ্য আছে। এবং আমি একটি ভাল অভিজ্ঞতা আছে। এবং তারপর আমি একটি ভাল অভিজ্ঞতা লাভ করেছি। এবং আমি জানি যে, আমি কি না? আমি জানি, আমি কি, আমি জানি, আমি জানি, আমি কি, আমি জানি, আমি কি, আমি জানি, আমি কি করতে পারি? এবং আমি কি করি, আমি জানি, আমি জানি, আমি কি করি, আমি জানি, আমি জানি, আমি এটা কি করি? ঈশ্বর যদি তাঁর জন্য প্রার্থনা করেন, তা হলে তিনি তাকে এখানে হত্যা করার মাধ্যমে তার কাজগুলো উদ্ধার করবেন, এমন একজন ব্যক্তি বলতে পারবেন: “আমি কি সত্যিই তোমাদের জন্য চিন্তা করি? ” যে লোক এই জন ্ য বেঁচে থাকবে সে-ই হবে সাহায ্ য করবে । যে লোক এই জন ্ য বেঁচে থাকবে সেটি তবে নিশ ্ চয় সাফল ্ য । যে তার ইচ্ছার কথা বলতে পারবে সে হবে। ওহ, যে তার ইচ্ছার কথা বলতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالُوا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏وَبَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏: ‏ ‏ابْنُ وَرْدَانَ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏مُجَاهِدُ بْنُ وَرْدَانَ ‏ ‏مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏وَأَثْنَوْا عَلَيْهِ خَيْرًا ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏تُوُفِّيَ مَوْلًى لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِيرَاثِهِ فَقَالَ هَا هُنَا أَحَدٌ مِنْ أَهْلِ قَرْيَتِهِ قَالَ ‏ ‏بَهْزٌ ‏ ‏قَالُوا نَعَمْ قَالَ فَأَعْطُوهُ إِيَّاهُ ‏","","",""],[24251,24251,"","আমরা আমাদের আবেগ সৃষ্টি করেছি... ...আমাদের তৈরি করা মাংসের দাড়ি দিয়ে তৈরি করা এই আবেগ দিয়ে। তার লোকেরা তখন বঞ্চিত হয়েছিল, তবে তা উত্তম ছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُحَمَّدِ بْنِ الْمُنْتَشِرِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَنَّهُ سَأَلَ ‏ ‏ابْنَ عُمَرَ ‏ ‏عَنْ الرَّجُلِ يَتَطَيَّبُ عِنْدَ إِحْرَامِهِ فَقَالَ لَأَنْ أَطَّلِيَ ‏ ‏بِقَطِرَانٍ ‏ ‏أَحَبُّ إِلَيَّ مِنْ أَنْ أَفْعَلَهُ قَالَ فَسَأَلَ أَبِي ‏ ‏عَائِشَةَ ‏ ‏وَأَخْبَرَهَا بِقَوْلِ ‏ ‏ابْنِ عُمَرَ ‏ ‏فَقَالَتْ يَرْحَمُ اللَّهُ ‏ ‏أَبَا عَبْدِ الرَّحْمَنِ ‏ ‏كُنْتُ أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَطُوفُ عَلَى نِسَائِهِ ثُمَّ يُصْبِحُ مُحْرِمًا يَنْتَضِحُ طِيبًا ‏","","",""],[24252,24252,"","আমরা একটি আবেগ কথা বলেছি যা প্রভুর জীবন বদলে দিতে চেষ্টা করে। ঈশ্বরের ইচ্ছা হল, তিনি তাঁর কাছে প্রার্থনা করবেন এবং কয়েক মাস থেকে বিজ্ঞানের দিন পর্যন্ত তাকে আত্মসমর্পণ করবেন। আমরা বলতে চাই, তিনি বিজ্ঞানের নামে একটি উচ্চারিত হয়েছেন। আমরা কি এই বিষয়ে কথা বলছি? এবং আমরা যদি বলি, আমরা এখন আমাদের জীবনের জন্য আমাদের চিন্তা করি, এবং আমরা কি করতে হবে? ঘুমোও।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَقِيقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ الْأَيَّامَ الْمَعْلُومَةَ مِنْ الشَّهْرِ فَقَالَتْ نَعَمْ ‏","","",""],[24253,24253,"","আমরা আবেগ নিয়ে কথা বলেছি এবং আমার বাবার দুই বছর বয়স নিয়ে খেলতে চাই। ঈশ্বর তাকে আদেশ দিয়েছেন এবং বলেছেন, ঈশ্বর তাকে আদেশ দিয়েছেন। আমার একটা পছন্দ ছিল, আমি তাদের কাছাকাছি থেকে আপনাদের বলছি, যখন আমরা আমার বাবার সাথে লড়াই করার কথা বলেছিলাম। একবার আপনি একজন জীবিতকে দোষ দিলেন তার জন্য ঈশ্বরের কাছে অনুরোধ করবেন এবং তাকে জিজ্ঞেস করবেন। তার শান্তির জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ابْنُ عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ ‏ ‏إِنَّ لِي جَارَيْنِ فَإِلَى أَيِّهِمَا أُهْدِي قَالَ أَقْرَبِهِمَا مِنْكِ بَابًا ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏رَجُلٌ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏مِنْ ‏ ‏بَنِي تَيْمِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا سَأَلَتْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[24254,24254,"","আমরা ভালো মেজাজ গড়ে তোলার চেষ্টা করেছি, আমি আমার বিচার নিয়ে কথা বলেছি... ...ভালো ভাবে বিচার করার জন্য। আমার কাছে প্রভুর জীবনের জন্য দুইটা ভালো আগ্রহ আছে... আমি আমার মনের মধ্যে থাকা অবস্থায় ক্লান্ত হয়ে পড়েছি এবং খুন করার চেষ্টা করেছি। আমি মানুষকে আদেশ দিয়েছি যেন তারা তাদের আদেশ দেয়, যেন তারা তাদের এই আইনের যোগ্য হয়। আমার কাছে হুমকির বিষয় হচ্ছে, আমি এটা কিনব... ...আর তারপর আমি সমাধান করবো... ...সে বলতে চায় সে কী করতে চায়.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ حُسَيْنٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏سَمِعْتُ ‏ ‏عَلِيَّ بْنَ حُسَيْنٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏قَدِمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِأَرْبَعٍ مَضَيْنَ مِنْ ذِي الْحِجَّةِ فَدَخَلَ عَلَيَّ وَهُوَ غَضْبَانُ فَقُلْتُ مَنْ أَغْضَبَكَ يَا رَسُولَ اللَّهِ أَدْخَلَهُ اللَّهُ النَّارَ فَقَالَ ‏ ‏وَمَا شَعَرْتِ أَنِّي أَمَرْتُ النَّاسَ بِأَمْرٍ فَأَرَاهُمْ يَتَرَدَّدُونَ ‏ ‏قَالَ ‏ ‏الْحَكَمُ ‏ ‏كَأَنَّهُمْ أَحْسَبُ ‏ ‏وَلَوْ أَنِّي اسْتَقْبَلْتُ مِنْ أَمْرِي مَا اسْتَدْبَرْتُ مَا سُقْتُ الْهَدْيَ مَعِي حَتَّى أَشْتَرِيَهُ ثُمَّ أَحِلَّ كَمَا أَحَلُّوا ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏يَتَرَدَّدُونَ فِيهِ قَالَ كَأَنَّهُمْ هَابُوا أَحْسَبُ ‏","","",""],[24255,24255,"","আমরা একটি আবেগ কথা বলেছি যে আমরা জাতির আত্মার বিচার-এর রাজত্বের ব্যাপারে কথা বলেছি। একটি বিয়ার কিনে তাকে হত্যা করার চেষ্টা করছি। তিনি বললেন কখন এটি কিনতে হবে। টিভোর ছিল তার চেহারা থেকে মনোনীত আর তাকে স্বাধীন করা আর আমি মুক্ত তার চেহারা থেকে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَرَادَتْ أَنْ تَشْتَرِيَ ‏ ‏بَرِيرَةَ ‏ ‏لِلْعِتْقِ فَأَرَادَ ‏ ‏مَوَالِيهَا ‏ ‏أَنْ يَشْتَرِطُوا ‏ ‏وَلَاءَهَا ‏ ‏فَذَكَرَتْ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اشْتَرِيهَا إِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ وَخَيَّرَهَا مِنْ زَوْجِهَا وَكَانَ زَوْجُهَا حُرًّا وَأُتِيَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِلَحْمٍ فَقِيلَ هَذَا مَا تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[24256,24256,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যেটা আমরা প্রভুর মৃত্যুর শাসন নিয়ে এসেছি। আমি বলেছিলাম প্রভুর বার্তাবাহকের মঙ্গলের দিকে তাকিয়ে, আমি তাকে চিনি আর তার ক্ষমতা আছে পার্থক্য করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏إِبْرَاهِيمَ ‏ ‏يُحَدِّثُ عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنَّمَا أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[24257,24257,"","আমরা একটি আবেগ নিয়ে কথা বলেছি যে আমরা তাকে জীবিত সম্পর্কে জ্ঞান নিয়ে এসেছি। কেন আমি আল্লাহর কাছে প্রার্থনা করব তার সর্বোত্তম অভিজ্ঞতার জন্য? লর্ড প্রার্থনা করলেন। তাকে আর আমি আত্মসমর্পণ করব না হয় তুমি আমাদের ভালোবাসো, তারপর তুমি আমাকে রক্ষা কর।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏لَمَّا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَنْفِرَ رَأَى ‏ ‏صَفِيَّةَ ‏ ‏عَلَى بَابِ ‏ ‏خِبَائِهَا ‏ ‏كَئِيبَةً أَوْ حَزِينَةً وَقَدْ حَاضَتْ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعَقْرَى ‏ ‏أَوْ حَلْقَى ‏ ‏إِنَّكِ ‏ ‏لَحَابِسَتُنَا ‏ ‏أَكُنْتِ أَفَضْتِ يَوْمَ النَّحْرِ قَالَتْ نَعَمْ قَالَ فَانْفِرِي إِذًا ‏","","",""],[24258,24258,"","আমরা এক সময় কথা বলেছি ১০ গুণের একটা জিনিস শুনে সে তার জন্য প্রার্থনা করতে শুনেছে এবং সে কোন শিক্ষককে বলবে না যে তার বাইক বা তার পরিকল্পনা আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَمْروِ بْنِ مُرَّةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا وَائِلٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَا مِنْ مُسْلِمٍ يُشَاكُ شَوْكَةً فَمَا فَوْقَهَا إِلَّا رَفَعَهُ اللَّهُ عَزَّ وَجَلَّ بِهَا دَرَجَةً أَوْ حَطَّ بِهَا عَنْهُ خَطِيئَةً ‏","","",""],[24259,24259,"","আমরা কামনার দ্বারা বাপ্তাইজিত হয়েছি, যা আমাকে আনন্দ কামনার কথা বলেছে, ঈশ্বর তার সন্তানের যুক্তিকে বলছে এবং আমরা তার পিতার মতোই কথা বলেছি আমি বলেছি যে ঈশ্বর তাকে আদেশ করেছেন বলে মনে হয়.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ بْنِ عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏ابْنُ عَوْفٍ ‏ ‏و حَدَّثَنَاه ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏ابْنُ عَبْدِ اللَّهِ بْنِ عُثْمَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَهْوَى ‏ ‏إِلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِيُقَبِّلَنِي فَقُلْتُ إِنِّي صَائِمَةٌ قَالَ وَأَنَا صَائِمٌ فَقَبَّلَنِي ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏قَالَ لِي ‏ ‏سَعْدٌ ‏ ‏طَلْحَةُ ‏ ‏عَمُّ ‏ ‏أَبِي سَعْدٍ ‏","","",""],[24260,24260,"","আমরা আবেগ দিয়ে আমাদের মনকে জয় করার চেষ্টা করেছি। একটি স্বপ্নের কথা বলে যে ঈশ্বর তাকে প্রার্থনা করেছেন এবং ঈশ্বরের প্রতি আমি যা ভালোবাসি তার কাছে প্রার্থনা করেছেন। তিনি বলেছিলেন, তিনি যেন তিনি বলেন। আগে কখনো টাকার থেকে খেতে হয়নি.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ أَيُّ الْعَمَلِ أَحَبُّ إِلَى اللَّهِ قَالَ أَدْوَمُهُ وَإِنْ قَلَّ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏مَا دُووِمَ عَلَيْهِ ‏ ‏وَقَالَ اكْلَفُوا مِنْ الْأَعْمَالِ مَا تُطِيقُونَ ‏","","",""],[24261,24261,"","আমরা তার সাথে কথা বলেছি, ভালোরা তাকে সাহায্য করার চেষ্টা করছে। স্কুইড খুশি হয়ে বললো, সে হয়ত বলবে সে অনেক লাভজনক।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏بَهْزٌ ‏ ‏أَخْبَرَنِي ‏ ‏سَعْدُ بْنُ إِبْرَاهِيمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي وَأَنَا بَيْنَهُ وَبَيْنَ الْقِبْلَةِ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏قَالَ ‏ ‏سَعْدٌ ‏ ‏وَأَحْسَبُهُ قَدْ قَالَ وَهِيَ حَائِضٌ ‏","","",""],[24262,24262,"","আমরা নিজেদের জোর করে সাহায্য করার চেষ্টা করেছি, আমরা তাকে সাহায্য করার চেষ্টা করেছি, আমরা তার সাথে কথা বলছি, আমি কার কথা বলবো, এমনকি একটি মোটা ছেলে এবং তার ছেলেও হতে পারে। আমি ভেবেছিলাম যে তিনি ভাল আছেন। জন্ম।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عُرْوَةَ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ أَسْمَعُ أَنَّهُ لَنْ يَمُوتَ نَبِيٌّ حَتَّى يُخَيَّرَ بَيْنَ الدُّنْيَا وَالْآخِرَةِ قَالَ فَسَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ وَأَخَذَتْهُ ‏ ‏بُحَّةٌ ‏ ‏يَقُولُ ‏ { ‏مَعَ الَّذِينَ أَنْعَمَ اللَّهُ عَلَيْهِمْ مِنْ النَّبِيِّينَ وَالصِّدِّيقِينَ وَالشُّهَدَاءِ وَالصَّالِحِينَ وَحَسُنَ أُولَئِكَ رَفِيقًا ‏} ‏قَالَتْ فَظَنَنْتُ أَنَّهُ خُيِّرَ حِينَئِذٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏إِنَّهُ خُيِّرَ بَيْنَ الدُّنْيَا وَالْآخِرَةِ ‏","","",""],[24263,24263,"","আমরা তার নিজের পরিবারের কাছে ঈশ্বরকে পাঠাতে বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏مُطَرِّفٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ فِي رُكُوعِهِ ‏ ‏سُبُّوحٌ قُدُّوسٌ رَبُّ الْمَلَائِكَةِ وَالرُّوحِ ‏","","",""],[24264,24264,"","আমরা বাবার কথা বলেছি একটি জীবন্ত জয়ের চেষ্টা করে। ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তিনি আমাকে আত্মসমর্পণ করবেন যে রাতে ঘুমোচ্ছে বা রাতে সে ছিল সেই সেই ব্যক্তি যে ছিল তিনিই সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি যিনি ছিলেন সেই ব্যক্তি । তার যদি এটা করার প্রয়োজন হতো, তাহলে তিনি তা শোনার জন্য অনুমতি পেতেন । আমরা বলেছিলাম যে, বাবা তার কাছে প্রার্থনা করতে শুনেছেন এবং তার আদর্শগুলো উল্লেখ করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِاللَّيْلِ فَقَالَتْ كَانَ ‏ ‏يَنَامُ أَوَّلَ اللَّيْلِ ثُمَّ يَقُومُ فَإِذَا كَانَ مِنْ السَّحَرِ أَوْتَرَ ثُمَّ أَتَى فِرَاشَهُ فَإِنْ كَانَ لَهُ حَاجَةٌ أَلَمَّ بِأَهْلِهِ فَإِذَا سَمِعَ الْأَذَانَ وَثَبَ فَإِنْ كَانَ جُنُبًا أَفَاضَ عَلَيْهِ الْمَاءَ وَإِلَّا تَوَضَّأَ ثُمَّ خَرَجَ إِلَى الصَّلَاةِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏أَبُو إِسْحَاقَ ‏ ‏أَخْبَرَنَا قَالَ سَمِعْتُ ‏ ‏الْأَسْوَدَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[24265,24265,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমার বাবার জন্য একটা সমস্যা এনেছে লর্ডকে মুগ্ধ করতে, আমি কখনো বলিনি সে কি করছে, আর আমি তাদের কাছে প্রার্থনা করিনি। জুসের পর.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏وَمَسْرُوقٍ ‏ ‏أَنَّهُمَا قَالَا نَشْهَدُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا كَانَ يَوْمُهُ الَّذِي يَكُونُ عِنْدِي إِلَّا ‏ ‏صَلَّاهُمَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي تَعْنِي الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ ‏","","",""],[24266,24266,"","আমরা বাবার সাথে মাতাল হওয়ার চেষ্টা করার ব্যাপারে কথা বলেছি। সে তার জন্য ঈশ্বরের কাছে বাস করছে। সে বলছিল সে আমার ভাই। যদি তুমি চেষ্টা কর, তুমি চেষ্টা করো, তুমি চেষ্টা করবে। সে তার দুটো দরজা তৈরি করেছে ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏لِلْأَسْوَدِ ‏ ‏حَدِّثْنِي عَنْ ‏ ‏أُمِّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ عَنْهَا ‏ ‏فَإِنَّهَا كَانَتْ ‏ ‏تُفْضِي إِلَيْكَ قَالَ أَخْبَرَتْنِي أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ بِجَاهِلِيَّةٍ لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏ثُمَّ لَجَعَلْتُ لَهَا بَابَيْنِ ‏ ‏فَلَمَّا مَلَكَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏هَدَمَهَا وَجَعَلَ لَهَا بَابَيْنِ ‏","","",""],[24267,24267,"","তিনি বলেছিলেন: “আমার দানের সর্বোত্তমটা আমি পড়েছি: আপনার টাকাপয়সা আমার বাবার জীবন ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ ‏ ‏أَحَبُّ الْعَمَلِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الَّذِي يَدُومُ عَلَيْهِ صَاحِبُهُ ‏","","",""],[24268,24268,"","আমি আপনার টাকার সব থেকে ভালোটা পড়েছি, যার ছেলে হয়তো একটা ছেলে ছিল। আমার বাবা আমার কাছে কখনো ঈশ্বরের জীবনের স্বপ্ন দেখছেন না। আমি আপনার জন্য স্বপ্ন দেখছি। যখন আমরা খেলা খেলছিলাম, আমি হেরে গেছি, প্রভু, সে সিঁড়ির কাছে প্রার্থনা করে... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন আর সে যদি আপনার সাথে কখনো দেখা না করে তাহলে তাকে আত্মসমর্পণ করবে. ঈশ্বরের বার্তা শুনে আমি খুশি হয়েছি, ঈশ্বর তোমার কাছে প্রতিজ্ঞা করেছেন যে তুমি পাথর নয়, সে সিঁড়ি দিয়ে আছে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ عَبْدِ اللَّهِ ‏ ‏أَنَّ ‏ ‏عَبْدَ اللَّهِ بْنَ مُحَمَّدِ بْنِ أَبِي بَكْرٍ الصِّدِّيقِ ‏ ‏أَخْبَرَ ‏ ‏عَبْدَ اللَّهِ بْنَ عُمَرَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَلَمْ تَرَيْ أَنَّ قَوْمَكِ حِينَ بَنَوْا ‏ ‏الْكَعْبَةَ ‏ ‏اقْتَصَرُوا ‏ ‏عَنْ قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ أَلَا تَرُدُّهَا عَلَى قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا ‏ ‏حِدْثَانُ ‏ ‏قَوْمِكِ بِالْكُفْرِ ‏ ‏قَالَ فَقَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ عُمَرَ ‏ ‏لَئِنْ كَانَتْ ‏ ‏عَائِشَةُ ‏ ‏سَمِعَتْ هَذَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا أُرَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَ ‏ ‏اسْتِلَامَ ‏ ‏الرُّكْنَيْنِ اللَّذَيْنِ يَلِيَانِ الْحِجْرَ إِلَّا أَنَّ ‏ ‏الْبَيْتَ ‏ ‏لَمْ يَتِمَّ عَلَى قَوَاعِدِ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَلَيْهِ السَّلَام ‏","","",""],[24269,24269,"","আমরা একটা নির্দিষ্ট মৃত্যুর ঘা নিয়ে পড়া নিয়ে কথা বলেছি। ঈশ্বরের কাছে জানতে চেয়েছে কে আমার সাথে আছে। তারপর তাদের সব কিছু সমাধান করা যাবে না। এমনকি আমি একটা জায়গা হারিয়েছি এবং আমরা স্বপ্ন দেখছি। আমি সন্দেহ করেছিলাম, তোমার লর্ডের ইচ্ছার ব্যাপারে সন্দেহ করেছিলাম। আমি যে নিদ্রা দিয়াছিলাম, তাহা তোমার বয়স ছিল তোমার বয়স, যে ছোট ছোট লোকেরা এই নিয়ে জন্মগ্রহণ করেছিল এরপর তারা আরেকটার পর একটা শিলার সমাধান করে ফেলে, যেটা তাদেরকে দেখতেও সুন্দর লাগে ।","‏ ‏حَدَّثَنَا ‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏وَحَدَّثَنَاهُ ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَامَ حَجَّةِ الْوَدَاعِ ‏ ‏فَأَهْلَلْنَا ‏ ‏بِعُمْرَةٍ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَانَ مَعَهُ هَدْيٌ ‏ ‏فَلْيُهِلَّ ‏ ‏بِالْحَجِّ مَعَ الْعُمْرَةِ ثُمَّ لَا يَحِلُّ حَتَّى يَحِلَّ مِنْهُمَا جَمِيعًا قَالَتْ فَقَدِمْتُ ‏ ‏مَكَّةَ ‏ ‏وَأَنَا حَائِضٌ وَلَمْ أَطُفْ ‏ ‏بِالْبَيْتِ ‏ ‏وَلَا بَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏فَشَكَوْتُ ذَلِكَ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏انْقُضِي ‏ ‏رَأْسَكِ وَامْتَشِطِي ‏ ‏وَأَهِلِّي ‏ ‏بِالْحَجِّ وَدَعِي الْعُمْرَةَ قَالَتْ فَفَعَلْتُ فَلَمَّا قَضَيْنَا الْحَجَّ أَرْسَلَنِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِى بَكْرٍ ‏ ‏إِلَى ‏ ‏التَّنْعِيمِ ‏ ‏فَاعْتَمَرْتُ فَقَالَ هَذِهِ مَكَانُ عُمْرَتِكِ قَالَتْ فَطَافَ الَّذِينَ ‏ ‏أَهَلُّوا ‏ ‏بِالْعُمْرَةِ ‏ ‏بِالْبَيْتِ ‏ ‏وَبَيْنَ ‏ ‏الصَّفَا ‏ ‏وَالْمَرْوَةِ ‏ ‏ثُمَّ حَلُّوا ثُمَّ طَافُوا طَوَافًا آخَرَ بَعْدَ أَنْ رَجَعُوا مِنْ ‏ ‏مِنًى ‏ ‏لِحَجِّهِمْ فَأَمَّا الَّذِينَ جَمَعُوا الْحَجَّ فَطَافُوا طَوَافًا وَاحِدًا ‏","","",""],[24270,24270,"","আমি যে - আশীর্বাদগুলো সম্বন্ধে পড়েছি, তা সম্বন্ধে পড়েছি: আপনার বাবা হয়তো আমার জন্য অনেক বেশি কিছু করেছেন । ঈশ্বর তাকে আমাদের ভালোবাসতে শিক্ষা দিয়েছেন, নাকি সে যখন তোমাকে বলবে, তখন সে তোমার সাথে থাকবে না","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏قَالَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏صَفِيَّةَ بِنْتَ حُيَيٍّ ‏ ‏قَدْ حَاضَتْ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَعَلَّهَا تَحْبِسُنَا ‏ ‏أَوَلَمْ تَكُنْ طَافَتْ مَعَكُنَّ ‏ ‏بِالْبَيْتِ ‏ ‏قَالُوا بَلَى قَالَ فَاخْرُجْنَ ‏","","",""],[24271,24271,"","তিনি তার কাছে আসেন এবং উত্তরে আসেন । ঈশ্বরের কাছে প্রার্থনা করো, সে জানতো আর আমি তাকে বলব যে আমি আমার আদেশ পালন করেছি তার অনুমতি নিয়ে।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّ ‏ ‏أَفْلَحَ ‏ ‏أَخَا ‏ ‏أَبِي الْقُعَيْسِ ‏ ‏جَاءَ يَسْتَأْذِنُ عَلَيْهَا وَهُوَ عَمُّهَا مِنْ الرَّضَاعَةِ بَعْدَ أَنْ نَزَلَ الْحِجَابُ قَالَتْ فَأَبَيْتُ أَنْ آذَنَ لَهُ فَلَمَّا جَاءَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْبَرْتُهُ بِالَّذِي صَنَعْتُ فَأَمَرَنِي أَنْ آذَنَ لَهُ ‏","","",""],[24272,24272,"","আমরা বাবার ছেলে তার বিয়ের ব্যাপারে কথা বলেছি... ...তার জীবন নিয়ে... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন... ...আর তিনি বজ্রের আলো দিয়ে আত্মসমর্পণ করবেন আর আমি এটা করবো।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ أَبِي ذِئْبٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا كَانَتْ تَقُولُ ‏ ‏مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسَبِّحُ سُبْحَةَ الضُّحَى وَإِنِّي لَأُسَبِّحُهَا ‏","","",""],[24273,24273,"","সে বলল আমি তোমার উপর বিশ্বাস করি আর আমরা তোমার টাকা মুছে ফেলতে চাই... ...আর তারপর আমার নিজের পথ মুছে ফেলার চেষ্টা করব. আমি প্রার্থনায় তার বিজ্ঞানের ওপর নির্ভর করতাম । সে আমাকে প্রায় হারিয়েই ফেলেছিল।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏وحَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ بْنِ أَبِي عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏أَهْدَى ‏ ‏أَبُو جَهْمِ بْنُ حُذَيْفَةَ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَمِيصَةً ‏ ‏شَامِيَّةً لَهَا ‏ ‏عَلَمٌ ‏ ‏فَشَهِدَ فِيهَا الصَّلَاةَ فَلَمَّا انْصَرَفَ قَالَ ‏ ‏رُدِّي هَذِهِ ‏ ‏الْخَمِيصَةَ ‏ ‏إِلَى ‏ ‏أَبِي جَهْمٍ ‏ ‏فَإِنِّي نَظَرْتُ إِلَى ‏ ‏عَلَمِهَا ‏ ‏فِي الصَّلَاةِ فَكَادَ يَفْتِنُنِي ‏","","",""],[24274,24274,"","ঈশ্বর তাঁর কাছে তাঁর শান্তি নিয়ে এসেছেন । আমি তোমাকে দেখতে পাবো কে তুমি তৈরি করতে পারবে, আমি কখনো ভাবিনি বের হতে দেওয়া থেকে বিরত নয়।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي الْمَسْجِدِ فَصَلَّى بِصَلَاتِهِ نَاسٌ ثُمَّ صَلَّى مِنْ الْقَابِلَةِ فَكَثُرَ النَّاسُ ثُمَّ اجْتَمَعُوا مِنْ اللَّيْلَةِ الثَّالِثَةِ ‏ ‏أَوْ الرَّابِعَةِ ‏ ‏فَلَمْ يَخْرُجْ إِلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا أَصْبَحَ قَالَ رَأَيْتُ الَّذِي صَنَعْتُمْ فَلَمْ يَمْنَعْنِي مِنْ الْخُرُوجِ إِلَيْكُمْ إِلَّا أَنِّي خَشِيتُ أَنْ تُفْرَضَ عَلَيْكُمْ وَذَلِكَ فِي رَمَضَانَ ‏","","",""],[24275,24275,"","তিনি আমাকে ক্ষমার অযোগ্যতার কথা বলেছেন: আপনার টাকা ছিল একটি হারমাসের বাবার জন্য, যে বাসায় তিনি বললেন ঈশ্বর তার জন্য প্রার্থনা করছেন এবং প্রভুর মৃত্যুর তিন বার প্রার্থনা করবেন।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي بِاللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً ثُمَّ ‏ ‏يُصَلِّي إِذَا سَمِعَ النِّدَاءَ بِالصُّبْحِ رَكْعَتَيْنِ خَفِيفَتَيْنِ ‏","","",""],[24276,24276,"","সে বলেছে, আমি তোমার টাকা নিয়ে পড়েছি, এক কনেকন্যার বিয়ের জন্য তার বাবার জন্য একটা পালক দিয়ে, তাকে এই খবর দিতে হবে যে সে ঈশ্বরের কাছে যাবে না। আমি ফিরে যেতে চাই, আর তিন বা দুই সেকেন্ড পড়তে চাই।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا أَخْبَرَتْهُ ‏ ‏أَنَّهَا لَمْ تَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي صَلَاةَ اللَّيْلِ قَاعِدًا حَتَّى أَسَنَّ فَكَانَ يَقْرَأُ قَاعِدًا حَتَّى إِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَقَرَأَ نَحْوًا مِنْ ثَلَاثِينَ أَوْ أَرْبَعِينَ آيَةً ثُمَّ رَكَعَ ‏","","",""],[24277,24277,"","তিনি বললেন, আমি ক্ষমার পর্দা পড়তে পড়েছি: আপনার টাকা আমার ছেলের আনন্দ বৃদ্ধি করতে। আমার বাবা তার জীবনের জন্য আশীর্বাদ করেছেন। গ্রেসের জন্য প্রার্থনা করছিল, আর সে একজন মহান গলি ছিল, তাই সে এটা তার পাঠকদের কাছ থেকে পড়তে পারত। তারপর সে চলে গেল, আর সে তোমার দ্বিতীয় তলায় ছিল।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏وَأَبِي النَّضْرِ ‏ ‏مَوْلَى ‏ ‏عُمَرَ بْنِ عُبَيْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي جَالِسًا فَيَقْرَأُ وَهُوَ جَالِسٌ فَإِذَا بَقِيَ عَلَيْهِ مِنْ قِرَاءَتِهِ قَدْرُ مَا يَكُونُ ثَلَاثِينَ أَوْ أَرْبَعِينَ آيَةً قَامَ فَقَرَأَ وَهُوَ قَائِمٌ ثُمَّ رَكَعَ ثُمَّ سَجَدَ ثُمَّ يَفْعَلُ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ ‏","","",""],[24278,24278,"","সে আমাকে বলেছে, তোমার টাকার সেরাটা আমি পড়েছি আমার বাবার জন্য, পাগলের বাসা তার কাছে প্রার্থনা করেছে আর সে বলেছে আমি বেঁচে আছি তার জন্য, হিজাবের ক্ষমতা এবং প্রার্থনা এই গৌরবময়তাকে জাগিয়ে তুলেছে, প্রাচীর চোরদের কাছে পৌঁছে গেছে এবং দুটি আইন আছে, আর তারপর আমি প্রভুর বার্তাবাহকের কাছ থেকে শুনেছি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنِ ‏ ‏الْقَعْقَاعِ بْنِ حَكِيمٍ ‏ ‏عَنْ ‏ ‏أَبِي يُونُسَ ‏ ‏مَوْلَى ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏أَمَرَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنْ أَكْتُبَ لَهَا مُصْحَفًا قَالَتْ إِذَا بَلَغْتَ هَذِهِ الْآيَةَ فَآذِنِّي ‏ { ‏حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى ‏} ‏قَالَ فَلَمَّا بَلَغْتُهَا آذَنْتُهَا فَأَمْلَتْ عَلَيَّ حَافِظُوا عَلَى الصَّلَوَاتِ وَالصَّلَاةِ الْوُسْطَى وَصَلَاةِ الْعَصْرِ وَقُومُوا لِلَّهِ قَانِتِينَ ثُمَّ قَالَتْ سَمِعْتُهَا مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24279,24279,"","তিনি বলেছিলেন, আমি আপনার ছেলের বিয়ের অনুষ্ঠানে শহীদের ছেলের জন্য আপনার সর্বোত্তম অর্থ সম্বন্ধে পড়েছি । ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তাঁর প্রতি ভয় দেখিয়ে কাজ করতে ইচ্ছুক এবং তিনি তাঁকে ভয় করতে চান ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنِ ‏ ‏ابْنِ شِهَابٍ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏مَا صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَةَ ‏ ‏الضُّحَى قَطُّ وَإِنِّي لَأُسَبِّحُهَا وَإِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيَدَعُ الْعَمَلَ وَهُوَ يُحِبُّ أَنْ يَعْمَلَ بِهِ خَشْيَةَ أَنْ يَعْمَلَ بِهِ النَّاسُ فَيُفْرَضَ عَلَيْهِمْ ‏","","",""],[24280,24280,"","তিনি বলেছিলেন যে, আমরা তোমার ভালবাসার কথা বলতে চেষ্টা করেছি । সে প্রভুর এই ক্ষতি থেকে মুক্তি পাবে, সে প্রভুর রুটি আর চোখের পানি দিয়ে হবে, আমি প্রভুর দোহাইর জন্য তার একটা হাসপাতাল দেখতে পাইনি কিন্তু এটাই সে করেছে। বিশ্বাস করুন ।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏قَالَ ‏ ‏وَحَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ عِيسَى ‏ ‏أَخْبَرَنِي ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏رَبِيعَةَ بْنِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَانَتْ فِي ‏ ‏بَرِيرَةَ ‏ ‏ثَلَاثُ سُنَنٍ إِحْدَى السُّنَنِ الثَّلَاثِ أَنَّهَا عُتِقَتْ فَخُيِّرَتْ فِي زَوْجِهَا وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ وَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْبُرْمَةُ ‏ ‏تَفُورُ بِلَحْمٍ فَقُرِّبَ إِلَيْهِ خُبْزٌ ‏ ‏وَأُدْمٌ ‏ ‏مِنْ ‏ ‏أُدْمِ ‏ ‏الْبَيْتِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَمْ أَرَ ‏ ‏بُرْمَةً ‏ ‏فِيهَا لَحْمٌ فَقَالُوا بَلَى يَا رَسُولَ اللَّهِ وَلَكِنَّ ذَلِكَ لَحْمٌ تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏وَأَنْتَ لَا تَأْكُلُ ‏ ‏الصَّدَقَةَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ ‏","","",""],[24281,24281,"","তিনি করুণার পর্দার উপর পড়েন: আপনার টাকা আমার বাবার উপর হয়ত এমন এক সময় এসেছিল যখন তিনি দয়া অনুভব করতেন। আমি তাকে বলেছি, তিনি তার ইচ্ছার কথা শোনেন। আমি বললাম, প্রভু। ঈশ্বরের কাছে প্রার্থনা করার জন্য আপনার নিজের বাড়িতে একজন ব্যক্তিকে অনুমতি দেওয়া হবে । মুখ, ঈশ্বর তাকে শিখিয়েছিলেন আর আমরা প্রেম করতে শিখি... ...তুমি যা অস্বীকার করছ তা অস্বীকার করা যায় না।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهَا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عِنْدَهَا وَأَنَّهَا سَمِعَتْ صَوْتَ رَجُلٍ يَسْتَأْذِنُ فِي بَيْتِ ‏ ‏حَفْصَةَ ‏ ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ يَا رَسُولَ اللَّهِ هَذَا رَجُلٌ يَسْتَأْذِنُ فِي بَيْتِكَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُرَاهُ فُلَانًا لِعَمٍّ ‏ ‏لِحَفْصَةَ ‏ ‏مِنْ الرَّضَاعَةِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ لَوْ كَانَ فُلَانٌ حَيًّا لِعَمِّهَا مِنْ الرَّضَاعَةِ أُدْخِلُ عَلَيَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَعَمْ ‏ ‏إِنَّ الرَّضَاعَةَ تُحَرِّمُ مَا تُحَرِّمُ الْوِلَادَةُ ‏","","",""],[24282,24282,"","তিনি ক্ষমার পর্দার উপর পড়েন: আপনার টাকা আমাকে ক্ষমা করে দিতে পেরে খুশি। নবী তার নিজের কাছে ক্ষমা প্রার্থনা করেছেন এবং বলেছেন তিনি হচ্ছেন তিনি লর্ড। সানস্যমান অনুযায়ী নারীরা এ কাজে নিয়োজিত।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ سَعِيدٍ الْأَنْصَارِيِّ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُصَلِّي الصُّبْحَ فَيَنْصَرِفُ النِّسَاءُ ‏ ‏مُتَلَفِّعَاتٌ ‏ ‏بِمُرُوطِهِنَّ ‏ ‏مَا يُعْرَفْنَ مِنْ ‏ ‏الْغَلَسِ ‏","","",""],[24283,24283,"","তিনি আমাকে ক্ষমার পর্দার উপর পড়েছিন: আপনার টাকা তার বাবার চেয়ে ভালো। ঈশ্বরের কাছে তার আনুগত্যের জন্য, তাকে ঈশ্বরের প্রভুর কাছে সমর্পণ করতে হয়েছে। লর্ড অথবা ঐ আত্মা আমাকে ঈশ্বরের দোহাই দিয়ে হত্যা করেছে, তার সাথে পানি নেই, আর তারা পানিও নয়, যা মানুষ অনেক কিছু বলে। উদ্ধার এবং মানুষ পানি ও কোন দয়া নেই, আমি আমার পিল নিয়ে যাব এবং বলে দিবো যে লর্ডের শান্তি আছে এবং মানুষ পানি স্পর্শ করবে। সে হয়তো আমার জায়গায় বিশ্বাস করতে পারে এবং কখনো করতে পারবে না। ঈশ্বর আমাকে ঈশ্বরের দিনে নিয়ে যেতে শিখিয়েছেন। যদি সে মানুষ হয়, সে আমাকে মেরে ফেলবে, সে তোমাকে নিয়ন্ত্রণ করতে পারবে না, দ্বিতীয় আমি হারটা পেয়ে গেছি।","‏ ‏قَالَ ‏ ‏قَرَأْتُ عَلَى ‏ ‏عَبْدِ الرَّحْمَنِ ‏ ‏: ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ زَوْجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ أَسْفَارِنَا حَتَّى إِذَا كُنَّا ‏ ‏بِالْبَيْدَاءِ ‏ ‏أَوْ ‏ ‏بِذَاتِ الْجَيْشِ ‏ ‏انْقَطَعَ عِقْدٌ لِي ‏ ‏فَأَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْتِمَاسِهِ وَأَقَامَ النَّاسُ مَعَهُ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَأَتَى النَّاسُ إِلَى ‏ ‏أَبِي بَكْرٍ ‏ ‏فَقَالُوا أَلَا ‏ ‏تَرَى مَا صَنَعَتْ ‏ ‏عَائِشَةُ ‏ ‏أَقَامَتْ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَبِالنَّاسِ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاضِعٌ رَأْسَهُ عَلَى فَخِذِي فَقَالَ ‏ ‏حَبَسْتِ ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالنَّاسَ وَلَيْسُوا عَلَى مَاءٍ وَلَيْسَ مَعَهُمْ مَاءٌ قَالَتْ فَعَاتَبَنِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَقَالَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ وَجَعَلَ يَطْعَنُ بِيَدِهِ فِي خَاصِرَتِي وَلَا يَمْنَعُنِي مِنْ التَّحَرُّكِ إِلَّا مَكَانُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فَخِذِي فَنَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى أَصْبَحَ النَّاسُ عَلَى غَيْرِ مَاءٍ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ ‏آيَةَ التَّيَمُّمِ ‏ ‏فَتَيَمَّمُوا فَقَالَ ‏ ‏أُسَيْدُ بْنُ الْحَضِيرِ ‏ ‏مَا هِيَ بِأَوَّلِ بَرَكَتِكُمْ يَا آلَ ‏ ‏أَبِي بَكْرٍ ‏ ‏قَالَتْ فَبَعَثْنَا الْبَعِيرَ الَّذِي كُنْتُ عَلَيْهِ فَوَجَدْنَا الْعِقْدَ تَحْتَهُ ‏","","",""],[24284,24284,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি আমাকে নেতা হিসেবে গ্রহণ করবেন এবং আমি একজন নেতা হব ।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏سَعْدٍ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏طَلْحَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُقَبِّلُنِي وَهُوَ صَائِمٌ وَأَنَا صَائِمَةٌ ‏","","",""],[24285,24285,"","আমরা প্রভুর দিনে আমাদের ভালবাসার আশীর্বাদের কথা বলেছিলাম, আমি তোমাকে শিক্ষা দিচ্ছি ঈশ্বর এবং ঈশ্বরের জীবন ফিরিয়ে দিতে হবে। মেজরের কাছে।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ شَدَّادٍ ‏ ‏عَنْ ‏ ‏أَبِي عُذْرَةَ ‏ ‏وَكَانَ قَدْ أَدْرَكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى الرِّجَالَ وَالنِّسَاءَ عَنْ الْحَمَّامَاتِ ثُمَّ رَخَّصَ لِلرِّجَالِ فِي ‏ ‏الْمَيَازِرِ ‏","","",""],[24286,24286,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাকে আত্মসমর্পণ করতে বলেছেন, এমন এক জগতে দীর্ঘ জীবন বেঁচে থাকতে হবে । আনন্দের জগৎ, আমরা এটা নিয়ে কথা বলেছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ مُحَمَّدِ بْنِ طَحْلَاءَ ‏ ‏عَنْ ‏ ‏أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏بَيْتٌ لَيْسَ فِيهِ تَمْرٌ جِيَاعٌ أَهْلُهُ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏كَانَ ‏ ‏سُفْيَانُ ‏ ‏حَدَّثَنَاهُ عَنْهُ ‏","","",""],[24287,24287,"","আমরা শপথের উষ্ণতা নিয়ে কথা বলেছিলাম কিন্তু শপথের শপথটা আমি একজন যাজককে চুরি করছি যে ঈশ্বরের ইচ্ছা পালন করে। আমি তাকে আদেশ দিয়েছি আর আমাকে যা করতে বলা হয়েছে তা করতে বলো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْأَزْرَقِ بْنِ قَيْسٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْأَزْرَقُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏ذَكْوَانَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي عَلَى ‏ ‏الْخُمْرَةِ ‏","","",""],[24288,24288,"","আমরা ঈশ্বর কথা বলেছি আমরা ঈশ্বরের ঈশ্বরের ঈশ্বরের কাছে কথা বলেছি। আমরা তো বলেছি, তার সময় তার হাতে নেই যখন আমরা বধিরদের নকল করার চেষ্টা করি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لِلْجَارِيَةِ وَهُوَ فِي الْمَسْجِدِ ‏ ‏نَاوِلِينِي ‏ ‏الْخُمْرَةَ ‏ ‏قَالَتْ أَرَادَ أَنْ يَبْسُطَهَا فَيُصَلِّيَ عَلَيْهَا فَقَالَتْ إِنِّي حَائِضٌ فَقَالَ إِنَّ حَيْضَتَهَا لَيْسَتْ فِي يَدِهَا ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ السُّدِّيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏فَذَكَرَهُ ‏","","",""],[24289,24289,"","আমরা ঈশ্বর কথা বলেছি আমরা যা বলেছি, তা নিয়ে কথা বলেছি। আমি ঈশ্বরের অনুগ্রহ থেকে বঞ্চিত হয়েছি এবং আমার সকল কিছুর উপর আত্মসমর্পণ করেছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنِ ‏ ‏السُّدِّيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ الْبَهِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا كُنْتُ أَقْضِي مَا يَبْقَى عَلَيَّ مِنْ رَمَضَانَ حَيَاةَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلَّهَا إِلَّا فِي شَعْبَانَ ‏","","",""],[24290,24290,"","তিনি বলেছিলেন আমরা প্রভুর হল থেকে বেনকে সাহায্য করার কথা বলেছিলাম। আমার মনে হয় যদি ঈশ্বর তার জন্য প্রার্থনা করেন এবং তিনি বলবেন যে আপনার শক্তি মূল্যহীন। আমি তাঁর সাথে খেলা করছিলাম। আমি এখন তাঁর সাথে খেলা করছি। আমি যদি তাঁর জন্য প্রার্থনা করি, তাহলে আমি আপনার জন্য একটি ভাল কাজ করব। এবং আমি আপনার জন্য একটি আদর্শ বার্তা নিয়ে আসব। এবং আপনি কি করবেন? আপনি কি আপনার শক্তি এবং আপনার শক্তি নিয়ে কথা বলতে চান? আপনি জানেন না? আপনি যদি আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি জানেন, আপনি আপনার শক্তি এবং আপনার শক্তি আপনার শক্তি আপনার জন্য একটি সহজ এবং আপনার শক্তি ব্যবহার করতে পারেন। এবং আপনি কি? এবং আপনার শক্তি আপনার জন্য একটি সহজ এবং আপনার জন্য তা নির্ধারণ করবেন। আপনি আপনার জন্য একটি বিষয় আপনার জন্য একটি বিষয় আপনার জন্য। এবং আপনি আপনার জন্য এটি আপনার জন্য একটি সহজ এবং আপনার জন্য। আপনি আপনার জন্য একটি সমাধান করতে পারেন। আপনার জন্য এটি আপনার জন্য একটি ভাল উপায় আছে। আপনি আপনার জন্য একটি সমাধান হবে। এবং আপনার জন্য ধন্যবাদ। আপনি আপনার জন্য ধন্যবাদ। আপনি যদি আপনি আপনার জন্য ধন্যবাদ। আপনি আপনার জন্য ধন্যবাদ। আপনি আপনার জন্য ধন্যবাদ। আপনি কি করবেন, আপনি কি করবেন? এবং আপনার জন্য ধন্যবাদ, আপনি আপনার জন্য ধন্যবাদ, আপনি কি করতে পারেন, আপনি কি আপনার জন্য ধন্যবাদ। আপনি কি আপনার জন্য ধন্যবাদ। আপনি আপনার জন্য পালিয়ে গিয়ে তাকে দুটো দরজা দিয়ে নিয়ে যেতে বাধ্য করে সে খেলা চলাকালীন গুলি করে।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ مِينَاءَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏يَقُولُ حَدَّثَتْنِي ‏ ‏خَالَتِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهَا ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثُ عَهْدٍ بِشِرْكٍ ‏ ‏أَوْ بِجَاهِلِيَّةٍ ‏ ‏لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏فَأَلْزَقْتُهَا بِالْأَرْضِ وَجَعَلْتُ لَهَا بَابَيْنِ بَابًا شَرْقِيًّا وَبَابًا غَرْبِيًّا وَزِدْتُ فِيهَا مِنْ الْحَجَرِ سِتَّةَ أَذْرُعٍ فَإِنَّ ‏ ‏قُرِيْشًا ‏ ‏اقْتَصَرَتْهَا حِينَ بَنَتْ ‏ ‏الْكَعْبَةَ ‏","","",""],[24291,24291,"","আমরা একজন যুবককে সাহায্য করার জন্য আপনার টাকা রক্ষা করার ব্যাপারে কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর তাকে যা বলতে হবে তা তাকে আত্মসমর্পণ করতে হবে, যেন তাকে প্রার্থনা করতে হয়। আমি তার প্রার্থনার ভাড়া নিয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ الْمُنْكَدِرِ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ جُبَيْرٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ امْرِئٍ يَكُونُ لَهُ صَلَاةٌ مِنْ اللَّيْلِ يَغْلِبُهُ عَلَيْهَا نَوْمٌ إِلَّا كَانَ نَوْمُهُ عَلَيْهِ ‏ ‏صَدَقَةً ‏ ‏وَكُتِبَ لَهُ أَجْرُ صَلَاتِهِ ‏","","",""],[24292,24292,"","আমি বললাম, আমি কিছু লোককে হত্যা করব যারা বলবে ঈশ্বর তাঁর কাছে প্রার্থনা করুক এবং তিনি তাঁর হাত এবং তাঁর হাত দিয়ে দেবেন। তারপর সে তার বাবাকে খুঁজে বের করবে যে আমি আল্লাহ্‌কে কিছু করব আর তাকে এর সমাধান করতে হবে। সে বলল, আমি শুনেছি যে ওই লোকটিও এটা করেছে। সে বলেছে, সে আমাকে বলেছে, ( ১ শমূ.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ بِنْتِ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدَيَّ ثُمَّ ‏ ‏يُقَلِّدُهَا ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِيَدِهِ ثُمَّ يَبْعَثُ بِهَا مَعَ أَبِي فَلَا يَدَعُ شَيْئًا أَحَلَّهُ اللَّهُ عَزَّ وَجَلَّ لَهُ حَتَّى يَنْحَرَ ‏ ‏الْهَدْيَ ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَلِيمُ بْنُ حَيَّانَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏خَالَتِهِ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ لِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنَّ قَوْمَكِ حَدِيثٌ عَهْدُهُمْ بِالشِّرْكِ لَهَدَمْتُ ‏ ‏الْكَعْبَةَ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏ابْنِ مَهْدِيٍّ ‏","","",""],[24293,24293,"","আমরা একজন শহীদের ছেলের কথা বলেছিলাম যে আমাদের ভালবাসার কথা বলেছিল। তিনি বলেছিলেন, তিনি ঈশ্বর যা চেয়েছেন, তার কাছে তাকে পাঠিয়ে দেয়া হবে এবং এমনকি তার লোকদের হাতে হস্তান্তর করা হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عُبَيْدِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا مَاتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى ‏ ‏أُحِلَّ ‏ ‏لَهُ النِّسَاءُ ‏","","",""],[24294,24294,"","আমরা একটা নাম নিয়ে কথা বলেছিলাম, যেটা ছিল এক ভালো ছেলে, যে বলেছিল আমরা একটা সময়ের জন্য শপথ নিয়েছি । যারা আগ্রহী তাদের কাছে সে আমাকে দিয়ে দেবে যদি সে আমাদের বাড়ি বানিয়ে দেয়। আর সেই ব্যাক্তি যাকে যুদ্ধ করার ক্ষমতা আছে তার জন্য গর্বিত। সে একটা উপহার পেয়েছিলো আর সে তার জন্য অমর ছিল যখন সে তার কাছে প্রার্থনা করছিল.","‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أُسَامَةُ بْنُ زَيْدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏الْقَاسِمُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ أُمَّ الْمُؤْمِنِينَ ‏ ‏تَقُولُ ‏ ‏إِنَّ ‏ ‏بَرِيرَةَ ‏ ‏كَانَتْ ‏ ‏مُكَاتِبَةً ‏ ‏لِأُنَاسٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَرَدْتُ أَنْ أَبْتَاعَهَا فَأَمَرْتُهَا أَنْ تَأْتِيَهُمْ فَتُخْبِرَهُمْ أَنِّي أُرِيدُ أَنْ أَبْتَاعَهَا فَأُعْتِقَهَا فَقَالُوا إِنْ جَعَلْتِ لَنَا ‏ ‏وَلَاءَهَا ‏ ‏ابْتَعْنَاهَا مِنْهَا فَاسْتَفْتَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏اشْتَرِيهَا فَأَعْتِقِيهَا فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْتَقَ وَدَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَالْمِرْجَلُ ‏ ‏يَفُورُ بِلَحْمٍ فَقَالَ مِنْ أَيْنَ لَكِ هَذَا قُلْتُ أَهْدَتْهُ لَنَا ‏ ‏بَرِيرَةُ ‏ ‏وَتُصُدِّقَ بِهِ عَلَيْهَا فَقَالَ هَذَا ‏ ‏لبَرِيرَةَ ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ قَالَتْ وَكَانَتْ تَحْتَ عَبْدٍ فَلَمَّا أَعْتَقَهَا قَالَ لَهَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اخْتَارِي فَإِنْ شِئْتِ أَنْ تَمْكُثِي تَحْتَ هَذَا الْعَبْدِ وَإِنْ شِئْتِ أَنْ تُفَارِقِيهِ ‏","","",""],[24295,24295,"","আমরা বেঁচে থাকার বিষয়ে কথা বলেছিলাম, যে - সম্বন্ধে আমাদের ভিতরে যেতে হবে । শত্রু, আমি গুলি করি বা আঘাত করি... ...আমাকে শাস্তি না দিতে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزُ بْنُ أَسَدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏عَنْ ‏ ‏عِكْرِمَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏دَخَلَ عَلَيَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِي فِي ‏ ‏إِزَارٍ ‏ ‏وَرِدَاءٍ فَاسْتَقْبَلَ الْقِبْلَةَ وَبَسَطَ يَدَهُ وَقَالَ ‏ ‏اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ فَأَيُّ عَبْدٍ مِنْ عِبَادِكَ ضَرَبْتُ أَوْ آذَيْتُ فَلَا تُعَاقِبْنِي فِيهِ ‏","","",""],[24296,24296,"","আমরা আমার প্রতিভার সবচেয়ে ভালো কথা বলেছি, ভালোর জন্য আমাদের নজর রাখার চেষ্টা করেছি। তাকে আত্মসমর্পণ করতে হয়েছে বলে যে, যদি তারা তাদের কাজ করে, তাহলে সে মারা যাবে না। হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تَسُبُّوا الْأَمْوَاتَ فَإِنَّهُمْ قَدْ أَفْضَوْا إِلَى مَا قَدَّمُوا ‏","","",""],[24297,24297,"","আমরা লাভা নিয়ে কথা বলেছি এবং আগুন থেকে আপনার মন্দের কথা বলছি । কাল তুমি দেরি করে ফেলেছ আর আমরা ঈশ্বরের চায়ের জন্য চা নিয়ে যাচ্ছি তারা কীভাবে কাজ করছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وحَدَّثَنَا ‏ ‏أَبُو عَامِرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏زُهَيْرُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏شَرِيكِ بْنِ نَمِرٍ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ يَسَارٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْرُجُ إِذَا كَانَتْ لَيْلَةُ ‏ ‏عَائِشَةَ ‏ ‏إِذَا ذَهَبَ ثُلُثَا اللَّيْلِ إِلَى ‏ ‏الْبَقِيعِ ‏ ‏فَيَقُولُ ‏ ‏السَّلَامُ عَلَيْكُمْ أَهْلَ دَارِ قَوْمٍ مُؤْمِنِينَ فَإِنَّا وَإِيَّاكُمْ وَمَا تُوعَدُونَ غَدًا مُؤَجَّلُونَ ‏ ‏قَالَ ‏ ‏أَبُو عَامِرٍ ‏ ‏تُؤَجَّلُونَ ‏ ‏وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ ‏","","",""],[24298,24298,"","আপনি বলেছিলেন, ঈশ্বর তাঁর কাছে প্রার্থনা করেন এবং তাকে প্রার্থনা করেন, যিনি তা করেন না বা করেন না ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ جَعْفَرٍ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏سَمِعَ ‏ ‏الْقَاسِمَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ عَمِلَ عَمَلًا لَيْسَ عَلَيْهِ أَمْرُنَا فَهُوَ رَدٌّ ‏","","",""],[24299,24299,"","আমি আমার বাবাকে তার জীবনের স্বপ্ন সম্বন্ধে জানতে সাহায্য করার বিষয়ে কথা বলেছিলাম । তার নিজের কথা, আমার বাবা ঈশ্বরের দোহাই, তুমি উড়তে পারো।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَيُّ الْأَعْمَالِ أَحَبُّ إِلَى اللَّهِ عَزَّ وَجَلَّ قَالَ أَدْوَمُهُ وَإِنْ قَلَّ ‏ ‏قَالَ ‏ ‏وَسَمِعْتُهُ ‏ ‏يَعْنِي ‏ ‏أَبَا سَلَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَوْ ‏ ‏عَنْ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اكْلَفُوا ‏ ‏مِنْ الْعَمَلِ مَا تُطِيقُونَ ‏","","",""],[24300,24300,"","আমি আমার বাবার সবচেয়ে ভালো কথা বলেছি, আমি ঈশ্বরের কাছে প্রার্থনা করব আর তিনি আমাকে এই কথা গুলো আমাকে দেবেন যে সেগুলো তাদের অনেক বার।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ أَبِي بَكْرٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَقِيلُو ‏ ‏ذَوِي ‏ ‏الْهَيْئَاتِ ‏ ‏عَثَرَاتِهِمْ ‏ ‏إِلَّا ‏ ‏الْحُدُودَ ‏","","",""],[24301,24301,"","আমরা ঈশ্বরের আগুন দিয়ে আমাদের সেরাটা করেছি। সে এটা করেছে। সে বলেছিল, সে এটা বিক্রি করেনি। ঈশ্বর, আমি ঈশ্বরের তিন বছরের মানুষের প্রতি আগ্রহী। আমার সাথে যে বাসাটা কথা বলেছিলাম, সে আমাকে তার মতো থাকতে বলেছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ مُرَّةَ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ ‏ ‏قَالَ ‏ ‏قَامَ فِينَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏وَالَّذِي لَا إِلَهَ غَيْرُهُ لَا يَحِلُّ دَمُ رَجُلٍ مُسْلِمٍ يَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَأَنِّي ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ إِلَّا ثَلَاثَةَ نَفَرٍ التَّارِكُ الْإِسْلَامَ وَالْمُفَارِقُ الْجَمَاعَةَ ‏ ‏وَالثَّيِّبُ ‏ ‏الزَّانِي وَالنَّفْسُ بِالنَّفْسِ ‏ ‏قَالَ ‏ ‏الْأَعْمَشُ ‏ ‏فَحَدَّثْتُ بِهِ ‏ ‏إِبْرَاهِيمَ ‏ ‏فَحَدَّثَنِي عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِمِثْلِهِ ‏","","",""],[24302,24302,"","আমরা তার বাবা-মা'র সবচেয়ে ভালো কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার অজ্ঞতার জন্য নিজেকে উৎসর্গ করেছেন যখন তিনি মারা যান, তখন আমি তাকে সমাধান করে দেব।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحُرْمِهِ حِينَ أَحْرَمَ ‏ ‏وَلِحِلِّهِ ‏ ‏حِينَ ‏ ‏أَحَلَّ ‏ ‏قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏","","",""],[24303,24303,"","আমি আমার বাবাকে খুন করতে চেয়েছিলাম, কে যেন বলেছিল আমি আমার ভাতিজাকে মেরে তাকে মেরে তাকে প্রহরী করে ফেলেছি, সে কখনো কোন মানুষের ক্ষতি করবে না। রক্ত, এমন মানুষ নয় যে চায় বা ছেড়ে দেয় না, এমনকি আমি আটকে পড়ার পরেও।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عَمْرِو بْنِ غَالِبٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لِلْأَشْتَرِ ‏ ‏أَنْتَ الَّذِي أَرَدْتَ قَتْلَ ابْنِ أُخْتِي قَالَ قَدْ حَرَصْتُ عَلَى قَتْلِهِ وَحَرَصَ عَلَى قَتْلِي قَالَتْ أَوَمَا عَلِمْتَ مَا قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ دَمُ رَجُلٍ إِلَّا رَجُلٌ ارْتَدَّ أَوْ تَرَكَ الْإِسْلَامَ أَوْ زَنَى بَعْدَمَا أُحْصِنَ أَوْ قَتَلَ نَفْسًا بِغَيْرِ نَفْسٍ ‏","","",""],[24304,24304,"","আমরা যুদ্ধের সাক্ষীর দুই মাস ধরে কথা বলেছি। আমার ছেলে তার জন্য প্রার্থনা করেছে এবং তার কল্পনা থেকে তাকে দূরে সরিয়ে দিয়েছে। তার পদের জন্য কিছু বিপদ দিতে বলেছে, দু ছেলে বেনকে দেখার জন্য আমার ছেলে হতে যাচ্ছে আর তার পরিবারের টাকা জানতে চায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ ‏ ‏مَوْلًى ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَّ ‏ ‏مِنْ ‏ ‏عَذْقِ ‏ ‏نَخْلَةٍ فَمَاتَ فَأُتِيَ بِهِ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ هَلْ لَهُ مِنْ نَسَبٍ أَوْ رَحِمٍ قَالُوا لَا قَالَ ‏ ‏أَعْطُوا مِيرَاثَهُ بَعْضَ أَهْلِ قَرْيَتِهِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏ابْنِ الْأَصْبَهَانِيِّ ‏ ‏عَنْ ‏ ‏مُجَاهِدِ بْنِ وَرْدَانَ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏فَدَفَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِيرَاثَهُ إِلَى أَهْلِ قَرْيَتِهِ ‏","","",""],[24305,24305,"","আমরা আমার বাবা জাদুকর আর কয়েক বছর আগে কথা বলেছি, আমার বাবার পাগলের কথা নিয়ে আমার বাবার একটা কথা শুনেছি। ঈশ্বরের ইচ্ছা পালন করতে হবে আর আমি তোমাদের ঈশ্বরের কাছে তোমার হাত তুলে দেব ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏عُمَارَةَ ‏ ‏عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏خَيْثَمَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِي عَطِيَّةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏إِنِّي لَأَعْلَمُ كَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَبِّي ‏ ‏لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏ثُمَّ سَمِعْتُهَا بَعْدُ لَبَّتْ ‏","","",""],[24306,24306,"","আমরা আমাদের জীবন্ত আলোচনা সম্পর্কে আমাদের সব থেকে ভালো আলোচনা করেছি, আমি কখনো লর্ডের প্রভুর কাছে প্রার্থনা করতে দেখিনি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي وَائِلٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ إِنْسَانًا قَطُّ أَشَدَّ عَلَيْهِ الْوَجَعُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[24307,24307,"","আমি আমার বাবাকে দুই মাস ধরে বাঁচিয়ে রাখার বিষয়ে বলেছিলাম । তাদের সকল সমবেদনা এবং তাদের ঈর্ষার কথা জানেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏رَخَّصَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَعْضِ الْأَمْرِ فَرَغِبَ عَنْهُ رِجَالٌ فَقَالَ ‏ ‏مَا بَالُ رِجَالٍ آمُرُهُمْ الْأَمْرَ يَرْغَبُونَ عَنْهُ وَاللَّهِ إِنِّي لَأَعْلَمُهُمْ بِاللَّهِ عَزَّ وَجَلَّ وَأَشَدُّهُمْ لَهُ خَشْيَةً ‏","","",""],[24308,24308,"","আমি আমার ফুলের জন্য আপনার টাকা সঞ্চয় করেছি একটি ভাল রাত স্বপ্নের জন্য. আমি তার শ্বাস এবং শ্বাস নিয়ে খুব অসুস্থ ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ كَانَ ‏ ‏إِذَا مَرِضَ يَقْرَأُ عَلَى نَفْسِهِ ‏ ‏بِالْمُعَوِّذَاتِ ‏ ‏وَيَنْفُثُ ‏","","",""],[24309,24309,"","আমরা তোমার জীবনের সেরা টাকা সম্পর্কে কথা বলেছি... ... দীর্ঘ জীবন ঈশ্বর আমাকে ভাল বোধ করেছেন, যদি তুমি বিশ্বাস না করো আমি তাকে এখানে পাঠাতে চাই, চলে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا اعْتَكَفَ يُدْنِي إِلَيَّ رَأْسَهُ أُرَجِّلُهُ وَكَانَ لَا يَدْخُلُ بَيْتَهُ إِلَّا لِحَاجَةِ الْإِنْسَانِ ‏","","",""],[24310,24310,"","আমরা আমার ফুলগুলোর জন্য তোমার টাকা সঞ্চয় করেছি... ...সে যা ভয় পায়, তাকে তা ছেড়ে দিতে হবে, সে এটা পছন্দ করে না, সে হয়তো এটা করতে পারে নি। ঈশ্বর আদেশ দিয়েছেন। আর তাকে এমন কিছুর থেকে আত্মসমর্পণ করবে যেটা মুক্ত হবে সেটা বুঝতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ إِلَّا اخْتَارَ أَيْسَرَهُمَا مَا لَمْ يَكُنْ فِيهِ إِثْمٌ فَإِذَا كَانَ فِيهِ إِثْمٌ كَانَ أَبْعَدَ النَّاسِ مِنْهُ وَمَا انْتَقَمَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِنَفْسِهِ مِنْ شَيْءٍ يُؤْتَى إِلَيْهِ إِلَّا أَنْ ‏ ‏تُنْتَهَكَ ‏ ‏حُرْمَةُ اللَّهِ فَيَنْتَقِمَ لِلَّهِ عَزَّ وَجَلَّ ‏","","",""],[24311,24311,"","আমরা আমার ফুলের জন্য আপনার টাকা সঞ্চয় করা সম্পর্কে কথা বলেছি যে আমার ঈশ্বর তাকে যেতে দিবেন না। তিনি রাতের একভাগ প্রার্থনা করছিলেন তার অভিজাত প্রার্থনার এক ভাগের এক ভাগ হবে। তাদের মধ্যে একজন ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي مِنْ اللَّيْلِ إِحْدَى عَشْرَةَ رَكْعَةً يُوتِرُ مِنْهَا بِوَاحِدَةٍ فَإِذَا فَرَغَ مِنْ صَلَاتِهِ اضْطَجَعَ عَلَى شِقِّهِ الْأَيْمَنِ ‏","","",""],[24312,24312,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি যদি আপনার ঘরে এবং তিনি যা - কিছু চান, সেগুলোর জন্য তিনি আত্মসমর্পণ করেছিলেন । ভয় পাচ্ছি, বিস্ফোরণ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ ‏ ‏يَا ‏ ‏أُمَّهْ ‏ ‏بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ عَلَيْكِ بَيْتَكِ وَبِأَيِّ شَيْءٍ كَانَ يَخْتِمُ قَالَتْ كَانَ يَبْدَأُ بِالسِّوَاكِ وَيَخْتِمُ بِرَكْعَتَيْ الْفَجْرِ ‏","","",""],[24313,24313,"","আমরা দশ বছর বয়সী এক শপথ-নে-প্রশ্ন-ব-ব-বয়েসীকে কথা বলেছি, আমি ইতোমধ্যে ঈশ্বরকে তার প্রার্থনা জিজ্ঞেস করেছি এবং তিনি তার পূর্বপরিকল্পিত কাজ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سَابَقْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَبَقْتُهُ ‏","","",""],[24314,24314,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি আমাকে তার ভার বহন করার জন্য প্রার্থনা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدُ بْنُ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ أَنَامُ مُعْتَرِضَةً بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي فَإِذَا أَرَادَ أَنْ يُوتِرَ ‏ ‏غَمَزَنِي ‏ ‏بِرِجْلِهِ فَقَالَ تَنَحَّيْ ‏","","",""],[24315,24315,"","আমরা তার মাকে বলেছিলাম যে, তার মা নীরব আছেন । সামনের বিল্ডিং.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ يَا ‏ ‏أُمَّهْ كَيْفَ كَانَتْ صَلَاةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ الْعِشَاءِ الْآخِرَةِ قَالَتْ كَانَ ‏ ‏يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً تِسْعًا قَائِمًا وَثِنْتَيْنِ جَالِسًا وَثِنْتَيْنِ بَعْدَ النِّدَاءَيْنِ ‏ ‏يَعْنِي بَيْنَ أَذَانِ الْفَجْرِ وَبَيْنَ الْإِقَامَةِ ‏","","",""],[24316,24316,"","আমরা বাবার কথা বলেছিলাম যে তিনি আমার বাবার বেঁচে থাকার স্বপ্নের কথা বলেছেন। শিকারীদের বন্ধু, যারা তাদের ছিল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ عَمْرٍو ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَقَدْ ‏ ‏كَانَ يَأْتِي عَلَى آلِ ‏ ‏مُحَمَّدٍ ‏ ‏الشَّهْرُ مَا يُرَى فِي بَيْتٍ مِنْ بُيُوتِهِ الدُّخَانُ قُلْتُ يَا ‏ ‏أُمَّهْ وَمَا كَانَ طَعَامُهُمْ قَالَتْ الْأَسْوَدَانِ التَّمْرُ وَالْمَاءُ غَيْرَ أَنَّهُ كَانَ لَهُ جِيرَانُ صِدْقٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَكَانَ لَهُمْ ‏ ‏رَبَائِبُ ‏ ‏فَكَانُوا يَبْعَثُونَ إِلَيْهِ مِنْ أَلْبَانِهَا ‏","","",""],[24317,24317,"","আমরা বাবার জীবন নিয়ে কথা বলেছি, ঈশ্বরের কাছে তার পতাকা পৌঁছে গেছে। তাকে মৃত্যুর মুখে ঠেলে দেওয়ার জন্য, সে কসমটা বলেছিল, তার সাহস আছে, আর সে তাকে হাতে তুলে দিয়েছে। সে বলেছে তার একটা খারাপ নাম ছিল, আর সে ভাবতো সে ভালো, আমি তাকে মিস করছি.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي وَجَعِهِ الَّذِي مَاتَ فِيهِ مَا فَعَلَتْ الذَّهَبُ قَالَتْ قُلْتُ وَهِيَ عِنْدِي قَالَ ائْتِينِي بِهَا فَجِئْتُ بِهَا وَهِيَ مَا بَيْنَ التِّسْعِ ‏ ‏أَوْ الْخَمْسِ ‏ ‏فَوَضَعَهَا فِي يَدِهِ ثُمَّ قَالَ بِهَا ‏ ‏وَأَشَارَ ‏ ‏يَزِيدُ ‏ ‏بِيَدِهِ ‏ ‏مَا ظَنُّ ‏ ‏مُحَمَّدٍ ‏ ‏بِاللَّهِ لَوْ لَقِيَ اللَّهَ عَزَّ وَجَلَّ وَهَذِهِ عِنْدَهُ أَنْفِقِيهَا ‏","","",""],[24318,24318,"","আমি আমার বাবার সাথে কথা বলেছি তাকে মারতে চেষ্টা করার জন্য।","‏ ‏قَالَ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنْ ‏ ‏أَبِي مَيْسَرَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏أُمُّ الْمُؤْمِنِينَ عَائِشَةُ ‏ ‏إِنْ كُنْتُ لَأَتَّزِرُ ثُمَّ أَدْخُلُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي لِحَافِهِ وَأَنَا حَائِضٌ ‏","","",""],[24319,24319,"","আমরা জীবন্ত জীবন নিয়ে কথা বলেছি, ঈশ্বর আমার জন্য প্রার্থনা করেছেন, তারপর ঘুমোলেন এবং পড়ে গেলেন, তারপর সে পড়ে গেল এবং এতো ভদ্র হয়ে গেল।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَجَّاجٌ ‏ ‏عَنْ ‏ ‏عَطَاءٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَجْنُبُ ثُمَّ يَنَامُ فَإِذَا قَامَ اغْتَسَلَ وَخَرَجَ وَرَأْسُهُ يَقْطُرُ ثُمَّ يَصُومُ بَقِيَّةَ ذَلِكَ الْيَوْمِ ‏","","",""],[24320,24320,"","আমরা ঈশ্বরের আশীর্বাদ নিয়ে কথা বলেছি যখন তিনি আমাদের লড়াই করতে বলেছিলেন। আমার কথা শুনে অমূল্য রাত পর্যন্ত, প্রভু আমাকে ক্ষমা করতে চান।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ فَبِمَ أَدْعُو قَالَ قُولِي ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24321,24321,"","আমরা অতীত বিয়ের কথা বলেছি, ঈশ্বর আদেশ দিয়েছেন আর ক্রুশে তিন রাত ধরে এই সাম্রাজ্যে পৌঁছেছেন। আমি তোমার আগের রাতে তোমার আগের চেয়ে বেশি আছি। আমি হয়তো তোমার মুখ শুনে শুনে অনেক সান্ত্বনা পেয়েছিলাম । বিখ্যাত।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَنَا ‏ ‏سُفْيَانُ يَعْنِي ابْنَ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَصَلَّى فِي الْمَسْجِدِ ذَاتَ لَيْلَةٍ فِي رَمَضَانَ وَصَلَّى خَلْفَهُ نَاسٌ بِصَلَاتِهِ ثُمَّ نَزَلَ اللَّيْلَةَ الثَّانِيَةَ فَكَانُوا أَكْثَرَ مِنْ ذَلِكَ ثُمَّ كَثُرُوا فِي اللَّيْلَةِ الثَّالِثَةِ فَلَمَّا كَانَتْ اللَّيْلَةُ الرَّابِعَةُ ‏ ‏غَصَّ ‏ ‏الْمَسْجِدُ بِأَهْلِهِ فَلَمْ يَنْزِلْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا فِي ذَلِكَ مَا شَأْنُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَنْزِلْ فَسَمِعَ مَقَالَتَهُمْ فَلَمَّا أَصْبَحَ قَالَ يَا أَيُّهَا النَّاسُ ‏ ‏إِنِّي قَدْ سَمِعْتُ مَقَالَتَكُمْ وَإِنَّهُ لَمْ يَمْنَعْنِي أَنْ أَنْزِلَ إِلَيْكُمْ إِلَّا مَخَافَةَ أَنْ يُفْتَرَضَ عَلَيْكُمْ قِيَامُ هَذَا الشَّهْرِ ‏","","",""],[24322,24322,"","আমি যা বলি সেটা হল, তুমি আমাকে ক্ষমা করতে ভালবাসো।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏كَهْمَسٌ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏قَالَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏يَا رَسُولَ اللَّهِ إِنْ وَافَقْتُ لَيْلَةَ الْقَدْرِ بِمَ أَدْعُو قَالَ قُولِي ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24323,24323,"","আমরা কথা বলেছি বাবার বাসা রক্ষা করার মৌসুম সম্পর্কে আমাদের বলার চেয়ে। আমি আমার বাবার কাছে ঈশ্বরের প্রার্থনার লর্ডকে খুন করছি, সে চলে যাবে এবং তাকে খুঁজে বের করবে। কোন সমস্যা হয়.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ بِهَا وَلَا يَدَعُ شَيْئًا مِمَّا كَانَ يَصْنَعُ قَبْلَ ذَلِكَ ‏","","",""],[24324,24324,"","আমি নিজেকে একজন পরাজিত ব্যক্তি বলে মনে করতাম আর আমি তাকে ছেড়ে দিতে চেয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏عَنْ ‏ ‏أَيُّوبَ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏سُئِلَتْ عَنْ رَكْعَتَيْ الْفَجْرِ فَقَالَتْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخَفِّفُهُمَا قَالَتْ فَأَظُنُّهُ كَانَ يَقْرَأُ بِنَحْوٍ مِنْ ‏ ‏قُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏","","",""],[24325,24325,"","আমরা এমন একজনের কথা বলেছিলাম যে তার পাশ দিয়ে যাওয়ার পর থেকে সে আমার সাথে চুমু খায়, তাই আমি তোমাকে কথা বলেছি যে বাচ্চাটি তার কাছে আসবে। তার কল্পনাই হবে। তার খ্যাতি মেনে নিয়েছিল, যখন সে লোকেদের বলেছিল, তারা তোমাকে ঘৃণা করে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏عَنْ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏أَنَّهُ قَالَ مَا اسْتَقْبَلْتُ الْقِبْلَةَ بِفَرْجِي مُنْذُ كَذَا وَكَذَا ‏ ‏فَحَدَّثَ ‏ ‏عِرَاكُ بْنُ مَالِكٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ ‏ ‏بِخَلَائِهِ ‏ ‏أَنْ يُسْتَقْبَلَ بِهِ الْقِبْلَةَ لَمَّا بَلَغَهُ أَنَّ النَّاسَ يَكْرَهُونَ ذَلِكَ ‏","","",""],[24326,24326,"","আমরা বিশ্বাস করি গ-বসে-এ-যাবক-এ কথা বলেছি, সে কি কি করতে হয়েছে সে বিষয়ে আমরা কথা বলেছি। সে একটা ছবি তোলার ভুল পথে চুরি করেছে এবং তারপর সে বিষগ্রস্ত হয়ে পরে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الثَّقَفِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصْبِحُ جُنُبًا مِنْ غَيْرِ احْتِلَامٍ ثُمَّ يَصُومُ ‏","","",""],[24327,24327,"","আমরা আমার বাবা এক বছরেরও বেশি সময় ধরে তার বাবার সাথে কথা বলেছি, ঈশ্বরের কাছে প্রার্থনা করা হয়েছে, ঈশ্বর কখনও কেঁদে নি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَيُّوبَ يَعْنِي أَبَا الْعَلَاءِ الْقَصَّابَ ‏ ‏عَنْ ‏ ‏أَبِي هَاشِمٍ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي جَالِسًا فَإِذَا أَرَادَ الرُّكُوعَ قَامَ فَقَرَأَ قَدْرَ عَشْرِ آيَاتٍ أَوْ مَا شَاءَ اللَّهُ ثُمَّ رَكَعَ ‏","","",""],[24328,24328,"","আমরা একজন বড় বন্ধুর সঙ্গে এক বড়ো সহমর্মী থাকার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏بُرْدٌ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ بَابُنَا فِي قِبْلَةِ الْمَسْجِدِ فَاسْتَفْتَحْتُ وَرَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَمَشَى حَتَّى فَتَحَ لِي ثُمَّ رَجَعَ إِلَى مَكَانِهِ الَّذِي كَانَ فِيهِ ‏","","",""],[24329,24329,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং প্রতিটা পুলিশ বইয়ের মধ্যে নয় বরং ঈশ্বরের কাছে আত্মসমর্পণ করার জন্য প্রার্থনা করেছিলেন । ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏أَخْبَرَنِي ‏ ‏سُفْيَانُ بْنُ حُسَيْنٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ بْنِ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كُلُّ شَرْطٍ لَيْسَ فِي كِتَابِ اللَّهِ عَزَّ وَجَلَّ فَهُوَ مَرْدُودٌ وَإِنْ اشْتَرَطُوا مِائَةَ مَرَّةٍ ‏","","",""],[24330,24330,"","আমরা একটা রাজধানী সম্পর্কে কথা বলেছিলাম, যেখানে আমরা ঈশ্বরের দোহাইের জন্য যুদ্ধ করতে পারি, আমি জানি আমি কি কারণে আমার প্রভু বা আমি দুঃখিত বলে ডাকছি কিনা। এই ভাসমান ভাসমান মানুষদের কথা আমাকে সাহায্য করেছে। আমি কি করতে পারি? আমি জানি না যে, এই ভাসমান অবস্থা আমাকে সাহায্য করবে। আমি কি করতে পারি? আমি জানি না। আমি জানি না যে, আমি সত্যিই দুঃখিত। আমি জানি, আমি জানি, আমি জানি না। আমি যদি আমার জীবনের মূল্য নির্ধারণ করি, আমি শুধু একটা জিনিসকে ভুলভাবে বলতে পারি। আমি কি,","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ أَرَأَيْتَ لَوْ أَنِّي عَلِمْتُ لَيْلَةَ الْقَدْرِ مَا كُنْتُ أَدْعُو بِهِ رَبِّي عَزَّ وَجَلَّ ‏ ‏أَوْ مَا كُنْتُ أَسْأَلُهُ ‏ ‏قَالَ قُولِي ‏ ‏اللَّهُمَّ إِنَّكَ عَفُوٌّ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي ‏","","",""],[24331,24331,"","আমরা সমুদ্রে ঈশ্বরকে নিয়ে কথা বলেছি... ...ঈশ্বর কে আমাদের সব থেকে খারাপের কথা বলেছে, তুমি ধরা পর মানুষ যাদের কাছে প্রার্থনা করো... তার প্রেমে পড়েছে, তার সাথে কথা বলছে যে এই প্রার্থনা কি, মানুষ ছেলে ও ঈশ্বরকে দেখে। আমি তার কথা বলছি, তারা হচ্ছে এই সন্তানের ছেলে। পাইলট, যে পাইলট পাইলট পাইলট সে পাইলটের ছেলের মাধ্যমে যাচ্ছে, কিন্তু সে তার জীবন ছেড়ে দিচ্ছে, সবাই প্রার্থনা করছে যে আমরা কখনোই এটা করতে পারি নি। ঈশ্বরের কাছে প্রার্থনা করে তার নিজের শান্তিয় তিনি তাঁর প্রার্থনা রক্ষা করেছেন। পাইলট যখন বললো যে সে নিজের জন্য ঈশ্বরের হয়ে কাজ করবে, আমি তোমাকে প্রার্থনা করতাম তুমি কখনো এটা না বললে, আমার শিল্পীর দৃষ্টি প্রার্থনায় ফোন করা হয়েছে তাদের কাছে হয়তো কোনো প্রার্থনা না - ও হতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏حَنْظَلَةُ السَّدُوسِيُّ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ بْنِ نَوْفَلٍ ‏ ‏قَالَ ‏ ‏صَلَّى ‏ ‏مُعَاوِيَةُ ‏ ‏بِالنَّاسِ الْعَصْرَ فَالْتَفَتَ فَإِذَا أُنَاسٌ يُصَلُّونَ بَعْدَ الْعَصْرِ فَدَخَلَ وَدَخَلَ عَلَيْهِ ‏ ‏ابْنُ عَبَّاسٍ ‏ ‏وَأَنَا مَعَهُ فَأَوْسَعَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏عَلَى السَّرِيرِ فَجَلَسَ مَعَهُ قَالَ مَا هَذِهِ الصَّلَاةُ الَّتِي رَأَيْتُ النَّاسَ يُصَلُّونَهَا وَلَمْ أَرَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّيهَا وَلَا أَمَرَ بِهَا قَالَ ذَاكَ مَا ‏ ‏يُفْتِيهِمْ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَدَخَلَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏فَسَلَّمَ فَجَلَسَ فَقَالَ ‏ ‏مُعَاوِيَةُ ‏ ‏يَا ‏ ‏ابْنَ الزُّبَيْرِ ‏ ‏مَا هَذِهِ الصَّلَاةُ الَّتِي تَأْمُرُ النَّاسَ يُصَلُّونَهَا لَمْ نَرَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهَا وَلَا أَمَرَ بِهَا قَالَ حَدَّثَتْنِي ‏ ‏عَائِشَةُ أُمُّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّاهَا عِنْدَهَا فِي بَيْتِهَا قَالَ فَأَمَرَنِي ‏ ‏مُعَاوِيَةُ ‏ ‏وَرَجُلٌ آخَرُ أَنْ نَأْتِيَ ‏ ‏عَائِشَةَ ‏ ‏فَنَسْأَلَهَا عَنْ ذَلِكَ قَالَ ‏ ‏فَدَخَلْتُ عَلَيْهَا فَسَأَلْتُهَا عَنْ ذَلِكَ فَأَخْبَرْتُهَا بِمَا أَخْبَرَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏عَنْهَا فَقَالَتْ لَمْ يَحْفَظْ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏إِنَّمَا حَدَّثْتُهُ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى هَذِهِ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ عِنْدِي فَسَأَلْتُهُ قُلْتُ إِنَّكَ صَلَّيْتَ رَكْعَتَيْنِ لَمْ تَكُنْ تُصَلِّيهِمَا قَالَ إِنَّهُ كَانَ أَتَانِي شَيْءٌ فَشُغِلْتُ فِي قِسْمَتِهِ عَنْ الرَّكْعَتَيْنِ بَعْدَ الظُّهْرِ وَأَتَانِي ‏ ‏بِلَالٌ ‏ ‏فَنَادَانِي بِالصَّلَاةِ فَكَرِهْتُ أَنْ أَحْبِسَ النَّاسَ فَصَلَّيْتُهُمَا ‏ ‏قَالَ ‏ ‏فَرَجَعْتُ فَأَخْبَرْتُ ‏ ‏مُعَاوِيَةَ ‏ ‏قَالَ قَالَ ‏ ‏ابْنُ الزُّبَيْرِ ‏ ‏أَلَيْسَ قَدْ صَلَّاهُمَا فَلَا نَدَعُهُمَا فَقَالَ لَهُ ‏ ‏مُعَاوِيَةُ ‏ ‏لَا تَزَالُ مُخَالِفًا أَبَدًا ‏","","",""],[24332,24332,"","আমরা ঈশ্বরের দোহাই এক বছর কথা বলেছি দেবতার মায়ের ব্যাপারে জানার জন্য। ঈশ্বর এটা করেছেন এবং আপনি যে শান্তি বলেছেন তা হল শান্তি আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنِ ‏ ‏الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ الْحَارِثِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا سَلَّمَ مِنْ الصَّلَاةِ قَالَ ‏ ‏اللَّهُمَّ أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ تَبَارَكْتَ يَا ذَا الْجَلَالِ وَالْإِكْرَامِ ‏","","",""],[24333,24333,"","আমরা একটা রাজধানী সম্বন্ধে কথা বলেছিলাম, যেখানে তার সঙ্গে এমন একটা জীবন থাকবে, যা তার সঙ্গে হবে । আমি বলেছিলাম, প্রভু, আপনি আমাকে সতেজতার জন্য ফোন করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ قَبْلَ مَوْتِهِ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ قَالَتْ وَكَانَ يُكْثِرُ أَنْ يَقُولَهُ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّكَ تَدْعُو بِدُعَاءٍ لَمْ تَكُنْ تَدْعُو بِهِ قَبْلَ الْيَوْمِ فَقَالَ إِنَّ رَبِّي عَزَّ وَجَلَّ أَخْبَرَنِي أَنِّي ‏ ‏سَأَرَى عَلَمًا فِي أُمَّتِي وَأَنِّي إِذَا رَأَيْتُ ذَلِكَ الْعَلَمَ أَنْ أُسَبِّحَ بِحَمْدِهِ وَأَسْتَغْفِرَهُ فَقَدْ رَأَيْتُ ذَلِكَ ‏ { ‏إِذَا جَاءَ نَصْرُ اللَّهِ وَالْفَتْحُ وَرَأَيْتَ النَّاسَ يَدْخُلُونَ فِي دِينِ اللَّهِ أَفْوَاجًا ‏}","","",""],[24334,24334,"","আমরা বাবার করা এক রাজধানীর কথা বলেছিলাম, একজন পাপীর প্রতি করুণা দেখানোর জন্য যে দেবতা হতে চেয়েছিল, সে আমাকে বলল যে সে একদিন আমাকে শাসন করবে। কাপুরুষের মত সে তাদের একজনকে খুন করার আগেই সে ভিক্ষা করছে আর সে চুপ থাকে, আর বলেছে যে অন্যটা কাপুরুষের দ্বারা আঘাত পেয়েছে। বাবা ও সেইসঙ্গে আমি যা বলেছি, তা - ই মনে করে তিনি লোকেদের অনুভব করতে চেয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَتَّابٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏يَقُولُ مَنْ أَصْبَحَ جُنُبًا فَلَا صَوْمَ لَهُ قَالَ فَأَرْسَلَنِي ‏ ‏مَرْوَانُ بْنُ الْحَكَمِ ‏ ‏أَنَا وَرَجُلًا آخَرَ إِلَى ‏ ‏عَائِشَةَ ‏ ‏وَأُمِّ سَلَمَةَ ‏ ‏نَسْأَلُهُمَا عَنْ ‏ ‏الْجُنُبِ ‏ ‏يُصْبِحُ فِي رَمَضَانَ قَبْلَ أَنْ يَغْتَسِلَ قَالَ فَقَالَتْ إِحْدَاهُمَا قَدْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصْبِحُ جُنُبًا ثُمَّ يَغْتَسِلُ وَيُتِمُّ صِيَامَ يَوْمِهِ قَالَ وَقَالَتْ الْأُخْرَى كَانَ يُصْبِحُ جُنُبًا مِنْ غَيْرِ أَنْ يَحْتَلِمَ ثُمَّ يُتِمُّ صَوْمَهُ قَالَ فَرَجَعَا فَأَخْبَرَا ‏ ‏مَرْوَانَ ‏ ‏بِذَلِكَ فَقَالَ ‏ ‏لِعَبْدِ الرَّحْمَنِ ‏ ‏أَخْبِرْ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏بِمَا قَالَتَا ‏ ‏فَقَالَ ‏ ‏أَبُو هُرَيْرَةَ ‏ ‏كَذَا كُنْتُ أَحْسَبُ وَكَذَا كُنْتُ أَظُنُّ قَالَ فَقَالَ لَهُ ‏ ‏مَرْوَانُ ‏ ‏بِأَظُنُّ ‏ ‏وَبِأَحْسَبُ ‏ ‏تُفْتِي النَّاسَ ‏","","",""],[24335,24335,"","আমরা একটি ঘোড়া এবং একটি উলকি সম্পর্কে কথা বলেছি যেখানে স্যারেনের একটি ছেলে তার শান্তি ও শান্তির জন্য এসেছে। তাদের মধ্যে একজন বললো, \" দূর হও, যাও, যাও, যাও, স্যারেনের পুত্র বলছে, ঈশ্বরের সর্বোচ্চ প্রভু আত্বসমর্পন করেছেন এবং তাদের কাছে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏وَهِشَامٍ ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقْرَأُ فِي رَكْعَتَيْ الْفَجْرِ ‏ ‏بِقُلْ يَا أَيُّهَا الْكَافِرُونَ ‏ ‏وَقُلْ هُوَ اللَّهُ أَحَدٌ ‏ ‏قَالَ ‏ ‏و حَدَّثَنَا ‏ ‏عَنْ ‏ ‏خَالِدٍ ‏ ‏يَعْنِي ‏ ‏عَلِيًّا ‏ ‏عَنِ ‏ ‏ابْنِ سِيرِينَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُسِرُّ بِهِمَا ‏","","",""],[24336,24336,"","আমরা বাবার সবচেয়ে ভালো মানুষ সম্পর্কে কথা বলেছি... ...সে আমাকে বাবার জীবন সম্পর্কে বলেছে, তার উত্তরাধিকারী বলেছে, সে তোমার টাকা নিয়ে যুদ্ধে গেছে... তারপর তুমি বলেছিলে তুমি আমাকে ঈশ্বরের দোহাই চাইতে বলবে, আর সে তাকে বদলে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏قَالَ ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏خَالِدِ بْنِ أَبِي الصَّلْتِ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ ‏ ‏عُمَرَ بْنِ عَبْدِ الْعَزِيزِ ‏ ‏فِي خِلَافَتِهِ قَالَ وَعِنْدَهُ ‏ ‏عِرَاكُ بْنُ مَالِكٍ ‏ ‏فَقَالَ ‏ ‏عُمَرُ ‏ ‏مَا اسْتَقْبَلْتُ الْقِبْلَةَ وَلَا اسْتَدْبَرْتُهَا بِبَوْلٍ وَلَا ‏ ‏غَائِطٍ ‏ ‏مُنْذُ كَذَا وَكَذَا ‏ ‏فَقَالَ ‏ ‏عِرَاكٌ ‏ ‏حَدَّثَتْنِي ‏ ‏عَائِشَةُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا بَلَغَهُ قَوْلُ النَّاسِ فِي ذَلِكَ ‏ ‏أَمَرَ بِمَقْعَدَتِهِ فَاسْتَقْبَلَ بِهَا الْقِبْلَةَ ‏","","",""],[24337,24337,"","আমরা আমাদের হত্যা করার কথা বলেছিলাম, হয়তো সে ভয়ে পালিয়ে যাচ্ছিল, ঈশ্বরের দোহাই তাকে এই অভ্যাস থেকে উদ্ধার করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏خَالِدٌ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَدْ كَانَتْ ‏ ‏تَخْرُجُ ‏ ‏الْكِعَابُ ‏ ‏مِنْ ‏ ‏خِدْرِهَا ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي الْعِيدَيْنِ ‏","","",""],[24338,24338,"","আমরা শপথ নিয়ে কথা বলেছি যে আমরা গ্রীষ্মের সময়ে ঈশ্বরের পুত্র সম্পর্কে কথা বলেছি যে গ্রীষ্মের সময়ে নবীের আদেশ দিয়েছেন নাকি ঈশ্বরের কাছে শপথ করেছেন ঈশ্বরের ওপর বিশ্বাস করে এমন একজন মহিলা তিন দিন গণনা করা বন্ধ করে দেন ।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏وَرْقَاءُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏صَفِيَّةَ ‏ ‏تَقُولُ قَالَتْ ‏ ‏عَائِشَةُ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَوْ ‏ ‏حَفْصَةُ ‏ ‏أَوْ هُمَا ‏ ‏تَقُولَانِ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللَّهِ أَنْ ‏ ‏تُحِدَّ ‏ ‏فَوْقَ ثَلَاثَةِ أَيَّامٍ إِلَّا عَلَى زَوْجِهَا ‏","","",""],[24339,24339,"","আমরা সিংহাসনে জন্মের কথা বলেছিলাম, আমি তার কাছে প্রার্থনা করেছি আর তার আত্মার কাছে আত্মসমর্পণ করেছি, আমি তোমাকে খুঁজে বের করবো আর ফিরে আসবো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏يَعْلَى بْنِ عَطَاءٍ ‏ ‏عَنِ ‏ ‏الْوَلِيدِ بْنِ عَبْدِ الرَّحْمَنِ الْقُرَشِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏حِضْتُ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى فِرَاشِهِ ‏ ‏فَانْسَلَلْتُ ‏ ‏فَقَالَ لِي أَحِضْتِ فَقُلْتُ نَعَمْ قَالَ ‏ ‏فَشُدِّي عَلَيْكِ ‏ ‏إِزَارَكَ ‏ ‏ثُمَّ عُودِي ‏","","",""],[24340,24340,"","ভাল কথা বলতে শুনেছি যে বিশ্বস্ত মায়ের কথা শুনেছি... ...ঈশ্বর তাকে আদেশ দিয়েছেন আর তার মৃত্যুর মঙ্গল কামনা করেছেন. আমরা সেই কারণ নিয়ে আলোচনা করেছি, যার কারণে তুমি কখনো প্যারেডে যেতে পারোনি।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ زِيَادٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ بْنُ حَمْزَةَ بْنِ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبَّادَ بْنَ عَبْدِ اللَّهِ بْنِ الزُّبَيْرِ ‏ ‏يَقُولُ سَمِعْتُ ‏ ‏أُمَّ الْمُؤْمِنِينَ عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏سَأَلْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ الْحِسَابِ الْيَسِيرِ فَقُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏مَا الْحِسَابُ الْيَسِيرُ فَقَالَ الرَّجُلُ تُعْرَضُ عَلَيْهِ ذُنُوبُهُ ثُمَّ يُتَجَاوَزُ لَهُ عَنْهَا إِنَّهُ مَنْ نُوقِشَ الْحِسَابَ هَلَكَ وَلَا يُصِيبُ عَبْدًا شَوْكَةٌ فَمَا فَوْقَهَا إِلَّا قَاصَّ اللَّهُ عَزَّ وَجَلَّ بِهَا مِنْ خَطَايَاهُ ‏","","",""],[24341,24341,"","আমি হয়তো আমার প্রভুকে হত্যা করেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তারপর তিনি সুস্থ হয়ে যাবেন ।","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجُ بْنُ مُحَمَّدٍ ‏ ‏عَنِ ‏ ‏ابْنِ جُرَيْجٍ ‏ ‏قَالَ أَخْبَرَ ‏ ‏ابْنُ شِهَابٍ ‏ ‏أَنَّ ‏ ‏عُرْوَةَ ‏ ‏أَخْبَرَهُ أَنَّ ‏ ‏عَائِشَةَ ‏ ‏أَخْبَرَتْهُ قَالَتْ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثُمَّ يَبْعَثُ بِهِ وَيُقِيمُ فَمَا يَتَّقِي مِنْ شَيْءٍ ‏","","",""],[24342,24342,"","আমরা অনেক ভয় পেয়েছি যে আমরা ভাল কিছু করেছি. তিনি আমাকে বলেছেন, \"ঈশ্বর আমাকে বলতে বলেছেন, আমি যখন তা করব, আমি তোমাকে বলতে চাই, আমি তোমাকে বলতে চাই, আমি ঈশ্বর ও তাঁর নির্দেশনা চাই এবং তাঁর নির্দেশনা চাই । ব্যবসা করে বলল যে সে ওই ছেলের হাতে ধরা পড়েছে, তোমার সাহস কখনো বলিনি আমি তাদের বলেছি যে সে ঈশ্বর আর তার লর্ডশিপের জন্য মনোনীত হয়েছে। টেবিল।","‏ ‏حَدَّثَنَا ‏ ‏كَثِيرُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جَعْفَرُ بْنُ بُرْقَانَ ‏ ‏قَالَ سَأَلْتُ ‏ ‏الزُّهْرِيَّ ‏ ‏عَنْ الرَّجُلِ يُخَيِّرُ امْرَأَتَهُ فَتَخْتَارُهُ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عُرْوَةُ بْنُ الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏أَتَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏إِنِّي سَأَعْرِضُ عَلَيْكِ أَمْرًا فَلَا عَلَيْكِ أَنْ لَا تَعْجَلِي فِيهِ حَتَّى تُشَاوِرِي أَبَوَيْكِ فَقُلْتُ وَمَا هَذَا الْأَمْرُ قَالَتْ فَتَلَا عَلَيَّ ‏ { ‏يَا أَيُّهَا النَّبِيُّ قُلْ لِأَزْوَاجِكَ إِنْ كُنْتُنَّ تُرِدْنَ الْحَيَاةَ الدُّنْيَا وَزِينَتَهَا فَتَعَالَيْنَ أُمَتِّعْكُنَّ ‏ ‏وَأُسَرِّحْكُنَّ ‏ ‏سَرَاحًا جَمِيلًا وَإِنْ كُنْتُنَّ تُرِدْنَ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ فَإِنَّ اللَّهَ أَعَدَّ لِلْمُحْسِنَاتِ مِنْكُنَّ أَجْرًا عَظِيمًا ‏} ‏قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏فَقُلْتُ وَفِي أَيِّ ذَلِكَ تَأْمُرُنِي أُشَاوِرُ أَبَوَيَّ بَلْ أُرِيدُ اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ قَالَتْ فَسُرَّ بِذَلِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَعْجَبَهُ وَقَالَ سَأَعْرِضُ عَلَى صَوَاحِبِكِ مَا عَرَضْتُ عَلَيْكِ قَالَتْ فَقُلْتُ لَهُ فَلَا تُخْبِرْهُنَّ بِالَّذِي اخْتَرْتُ فَلَمْ يَفْعَلْ وَكَانَ يَقُولُ لَهُنَّ كَمَا قَالَ ‏ ‏لِعَائِشَةَ ‏ ‏ثُمَّ يَقُولُ قَدْ اخْتَارَتْ ‏ ‏عَائِشَةُ ‏ ‏اللَّهَ وَرَسُولَهُ وَالدَّارَ الْآخِرَةَ قَالَتْ ‏ ‏عَائِشَةُ ‏ ‏قَدْ خَيَّرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمْ نَرَ ذَلِكَ طَلَاقًا ‏","","",""],[24343,24343,"","আমরা একজন দাসের সাথে কথা বলেছি যার হাতে আমরা কথা বলেছি, মানে আমার বাবার দুই বছর জীবন থেকে বেঁচে থাকা একজন ছেলে, আমি ঈশ্বরের অনুগ্রহের সন্তান, যিনি তাকে উদ্ধার করেছেন। আমি যখন সময় পার করেছি, সে আল্লাহ্‌র কাছে উল্লেখ করে বলেছিল যে, সে তার জন্য প্রার্থনা করে... ...আর সে তাকে না করতে বলে, তোমাকে উড়িয়ে দেয়া হবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ يَعْنِي ابْنَ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏عِمْرَانَ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ حَاضَتْ ‏ ‏صَفِيَّةُ بِنْتُ حُيَيٍّ ‏ ‏وَهِيَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِنًى ‏ ‏بَعْدَ أَنْ ‏ ‏أَفَاضَتْ ‏ ‏قَالَتْ فَلَمَّا كَانَ يَوْمُ ‏ ‏النَّفْرِ ‏ ‏ذُكِرَ ذَلِكَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَسَى أَنْ تَحْبِسَنَا قَالَ فَقِيلَ يَا رَسُولَ اللَّهِ إِنَّهَا قَدْ كَانَتْ طَافَتْ ‏ ‏بِالْبَيْتِ ‏ ‏قَالَ ‏ ‏فَلْتَنْفِرْ ‏","","",""],[24344,24344,"","আমরা দুই বছর ধরে কথা বলেছি, যাকে তুমি কখনো দেখবে না তার জন্য ভালোবাসায় ভ্রমণ করতে। মা আর মা কখনো খারাপ লোক হয় না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرِّ بْنِ حُبَيْشٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِينَارًا وَلَا دِرْهَمًا وَلَا أَمَةً وَلَا عَبْدًا وَلَا شَاةً وَلَا بَعِيرًا ‏","","",""],[24345,24345,"","আমরা আমার মেধার সবচেয়ে ভালো দিক নিয়ে কথা বলেছি, আমরা একজন মহিলার স্ত্রী সম্পর্কে আরো সন্দেহের কথা বলেছি। আমি প্রার্থনা করতে চাই যে আপনি ঈশ্বরের ইচ্ছা পালন করতে পারেন এবং তিনি আমার প্রভু হতে পারেন। আমি নিশ্চিত যে, আপনি ঈশ্বরের ইচ্ছা পালন করবেন। আমি আপনাকে প্রার্থনা করতে পারি, আপনি যদি আপনি ঈশ্বরের ইচ্ছা পালন করেন এবং তিনি হবেন। আমি আপনাকে তাঁর কাছে প্রার্থনা করি যে, আপনি আমার প্রভু হতে পারেন। এবং তিনি আমার প্রভু। এবং তিনি আমার প্রভু। আমি যদি আপনি আমাকে বলেন, আপনি আপনার সাথে আছেন, আপনি আপনার জন্য যা করবেন, তা হলে আপনি আপনার জন্য। এবং আপনি কি করবেন?","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَزِيدَ الرِّشْكِ ‏ ‏عَنْ ‏ ‏مُعَاذَةَ ‏ ‏أَنَّ امْرَأَةً سَأَلَتْ ‏ ‏عَائِشَةَ ‏ ‏أَتُجْزِئُ الْحَائِضُ الصَّلَاةَ قَالَتْ ‏ ‏أَحَرُورِيَّةٌ ‏ ‏أَنْتِ ‏ ‏قَدْ حِضْنَ نِسَاءُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفَأَمَرَهُنَّ أَنْ يَجْزِينَ ‏","","",""],[24346,24346,"","আমি আমার মৃত্যুর চেয়ে ভাল ছেলেকে নিয়ে কথা বলেছি। আমি আদেশ দিয়েছি যে আমি প্রভুর কাছে তার ছেলেকে আত্মসমর্পণ করবো... ...ঈশ্বর তাকে আদেশ দিয়েছেন যে ঈশ্বর তাকে আদেশ দিয়েছেন, সে এমন একজন মানুষ যে তাকে খেয়েছে, তারপর তাকে গুলি করা হয়েছে। পালানোর চেষ্টা করো, এমনকি এটা সংশোধন করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عُمَرَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنْ ‏ ‏أَبِي إِسْحَاقَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ يَزِيدَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِعَائِشَةَ أُمِّ الْمُؤْمِنِينَ ‏ ‏أَيُّ سَاعَةٍ تُوتِرِينَ لَعَلَّهُ قَالَتْ مَا ‏ ‏أُوتِرُ ‏ ‏حَتَّى يُؤَذِّنُونَ وَمَا يُؤَذِّنُونَ حَتَّى يَطْلُعَ الْفَجْرُ قَالَتْ وَكَانَ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُؤَذِّنَانِ ‏ ‏بِلَالٌ ‏ ‏وَعَمْرُو ابْنُ أُمِّ مَكْتُومٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَذَّنَ ‏ ‏عَمْرٌو ‏ ‏فَكُلُوا وَاشْرَبُوا فَإِنَّهُ رَجُلٌ ‏ ‏ضَرِيرُ ‏ ‏الْبَصَرِ وَإِذَا أَذَّنَ ‏ ‏بِلَالٌ ‏ ‏فَارْفَعُوا أَيْدِيَكُمْ فَإِنَّ ‏ ‏بِلَالًا ‏ ‏لَا يُؤَذِّنُ ‏ ‏كَذَا قَالَ ‏ ‏حَتَّى يُصْبِحَ ‏","","",""],[24347,24347,"","আমরা তার জীবিত থাকার ব্যাপারে কথা বলেছিলাম, আমি ঈশ্বরের বিশৃঙ্খলার দিকে তাকিয়ে দেখলাম আর তাকে কিছু দিন পর উদ্ধার করতে হবে আর সে খুব খারাপ হয়ে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَيَّامٍ وَهُوَ مُحْرِمٌ ‏","","",""],[24348,24348,"","ঈশ্বর তাঁর দয়া থেকে বঞ্চিত হওয়ার আগে তাকে আশীর্বাদ করেছেন এবং মুক্ত হওয়ার আগে তিনি তার দয়া দেখান ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏طَيَّبْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِطِيبٍ فِيهِ مِسْكٌ عِنْدَ إِحْرَامِهِ قَبْلَ أَنْ يُحْرِمَ وَيَوْمَ ‏ ‏النَّحْرِ ‏ ‏قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏","","",""],[24349,24349,"","আমি বাবার সাথে কথা বলেছিলাম, যখন অন্ধকার ছিল, আমি বলেছিলাম যে আমি ঈশ্বরের কাছে প্রার্থনা করেছি তার কাছে ভালো থাকবে আর আমি তার গলা ছেড়ে দেব যখন সে ছিল। আমরা যে বাড়িটার কথা বলেছিলাম... ...আমাদের টাকা নষ্ট করার কথা ছিল... ...আর দয়া করে... ...আর তার মত তারা তাকে বঞ্চিত করতে বলেনি.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ الْقَاسِمِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبِي ‏ ‏يُحَدِّثُ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِحُرْمِهِ حِينَ يُحْرِمُ ‏ ‏وَلِحِلِّهِ ‏ ‏حِينَ ‏ ‏يُحِلُّ ‏ ‏قَبْلَ أَنْ يَطُوفَ ‏ ‏بِالْبَيْتِ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مَالِكٌ ‏ ‏وصَخْرٌ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏بِمِثْلِهِ إِلَّا أَنَّهُمْ قَالُوا لِحُرْمِهِ قَبْلَ أَنْ يُحْرِمَ ‏","","",""],[24350,24350,"","তিনি বলেছিলেন, তিনি যদি ঈশ্বরের কাছে প্রার্থনা করতেন এবং তা রক্ষা করেছিলেন, তা হলে তিনি ঈশ্বরের কাছে প্রার্থনা করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ مَنْصُورٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْقَاسِمَ بْنَ مُحَمَّدٍ ‏ ‏وَيُوسُفَ بْنَ مَاهَكَ ‏ ‏وَعَطَاءً ‏ ‏يَذْكُرُونَ عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كُنْتُ ‏ ‏أُطَيِّبُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدَ إِحْلَالِهِ وَعِنْدَ إِحْرَامِهِ ‏","","",""],[24351,24351,"","আমরা আমার বাবার সাথে তার বাসা দেখানোর পর কথা বলেছি, সে বলল আমি ঈশ্বরের দোহাইর সাথে ঝামেলা করছি।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ مُحْرِمٌ ‏","","",""],[24352,24352,"","আমরা তাকে মৃত্যুর জীবন দিতে চেষ্টার কথা বলেছিলাম, আমি ঈশ্বরের বার্তাবাহকের মঙ্গলভাবের দিকে তাকিয়ে তার জন্য এসেছি এবং তার পরের দিন পর্যন্ত তার কাছে পৌঁছেছি এবং এটা অবিশ্বাস্য।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏عَطَاءِ بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَأَنِّي أَنْظُرُ إِلَى ‏ ‏وَبِيصِ ‏ ‏الطِّيبِ ‏ ‏فِي مَفْرِقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعْدَ أَيَّامٍ وَهُوَ مُحْرِمٌ ‏","","",""],[24353,24353,"","একবার তার খালার উপর লেখা আমার ছেলের নাম নিয়ে আমরা কথা বলেছি। একবার তার খালার উপর এক সময় বলেছিল যে এটা ঈশ্বরের শান্তি এবং ঈশ্বরের কাছে তার ইচ্ছা। বইয়ের সত্য তাদের মধ্যে আছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ عَبْدِ الْوَارِثِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَحْيَى يَعْنِي ابْنَ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏ابْنُ أَخِي عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَمَّتِهِ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ قَبْلَ ‏ ‏الْغَدَاةِ ‏ ‏فَيُخَفِّفُهُمَا حَتَّى إِنِّي لَأَشُكُّ أَقَرَأَ فِيهِمَا ‏ ‏بِفَاتِحَةِ الْكِتَابِ ‏ ‏أَمْ لَا ‏","","",""],[24354,24354,"","আমরা বাবার বিয়ের চোর সম্পর্কে কথা বলেছি, আমরা তার জীবন নিয়ে কথা বলেছি, ঈশ্বর এটা ত্যাগ করে নিয়ে যেতে হবে আর আপনি এটা বলবেন না যে আমি আমার ছেলে তোমাকে বলা হয়েছে. আপনি ঈশ্বরের মা.","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ حَفْصٍ أَبُو حَفْصٍ الْمُعَيْطِيُّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَلَا تَكْتَنِينَ قَالَتْ بِمَنْ ‏ ‏أَكْتَنِي قَالَ اكْتَنِي بِابْنِكِ ‏ ‏عَبْدِ اللَّهِ يَعْنِي ابْنَ الزُّبَيْرِ ‏ ‏قَالَ فَكَانَتْ ‏ ‏تُكَنَّى ‏ ‏بِأُمِّ عَبْدِ اللَّهِ ‏","","",""],[24355,24355,"","আমরা ছেলেটির বাচ্চার কথা বলেছিলাম... ...সে বলেছে তার সবারই আছে.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ وَلَدِ ‏ ‏الزُّبَيْرِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏كُلُّ نِسَائِكَ لَهَا كُنْيَةٌ غَيْرِي قَالَ أَنْتِ ‏ ‏أُمُّ عَبْدِ اللَّهِ ‏","","",""],[24356,24356,"","আমরা আমার বাবার স্বপ্নের কথা বলেছি, যাকে আমরা রক্ষা করেছি। আল্লাহ তার কাছে প্রার্থনা করেছেন এবং আগুনের শপথে আত্মসমর্পণ করেছেন।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ ‏آيَاتُ الرِّبَا ‏ ‏قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْمِنْبَرِ فَتَلَاهُنَّ عَلَى النَّاسِ ثُمَّ ‏ ‏حَرَّمَ التِّجَارَةَ فِي الْخَمْرِ ‏","","",""],[24357,24357,"","আমি যাকে বলেছি, সে তার প্রতি আনুগত্যের কথা বলেছে, যাকে আমি এই আগুন দিয়েছিলাম এবং আমি ঘুমাতে চেয়েছিলাম এবং প্রতারণার জন্য স্বাধীন ছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ أَعْطَى ‏ ‏الْوَرِقَ ‏ ‏وَأَعْتَقَ وَوَلِيِّ النِّعْمَةِ وَكَانَ زَوْجُهَا حُرًّا فَخُيِّرَتْ ‏","","",""],[24358,24358,"","আমরা একটি জীবন্ত জীবন্ত জীবনের জন্য পরিচিত হওয়ার আবেগ কথা বলেছি যে প্রেম ঈশ্বরের ইচ্ছা পালন করবে... ...সে আত্মসমর্পণ করবে... অথবা, আল্লাহ আছে আর তিনি ফোন করবেন, যাতে প্রত্যেক শক্তি ফিরে আসে আর আমরা ফিরে যাই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَتْ ‏ ‏الْحَبَشَةُ ‏ ‏يَلْعَبُونَ يَوْمَ عِيدٍ فَدَعَانِي رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكُنْتُ أَطَّلِعُ مِنْ ‏ ‏عَاتِقِهِ ‏ ‏فَأَنْظُرُ إِلَيْهِمْ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعْهَا ‏ ‏فَإِنَّ لِكُلِّ قَوْمٍ عِيدًا وَهَذَا عِيدُنَا ‏","","",""],[24359,24359,"","আমরা তোমার বাবার একজন গুরুতর অপরাধকারীর কথা বলেছি, ঈশ্বর তাকে আদেশ দিয়েছেন আর আত্মসমর্পণ করবে, যদি আমি পাপ করি, আমার কাছে ঈশ্বরের দোহাই আছে, টাকা কখনো না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏هِشَامِ بْنِ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏وَأَنْذِرْ عَشِيرَتَكَ الْأَقْرَبِينَ ‏} ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا ‏ ‏فَاطِمَةُ بِنْتُ مُحَمَّدٍ ‏ ‏يَا ‏ ‏صَفِيَّةُ بِنْتُ عَبْدِ الْمُطَّلِبِ ‏ ‏يَا ‏ ‏بَنِي عَبْدِ الْمُطَّلِبِ ‏ ‏لَا أَمْلِكُ لَكُمْ مِنْ اللَّهِ شَيْئًا سَلُونِي مِنْ مَالِي مَا شِئْتُمْ ‏","","",""],[24360,24360,"","আমরা আমার বাবার এক গ্রামের মানুষের জন্য ক্ষুধার কথা বলেছি, যে বলে যে তার তৃষ্ণার আগুন আছে। ভগবান আমার কাছে আছে বলে আমি দুজন প্রতিবেশী আছে যারা বলে যে তারা কাছাকাছি আছে। তুমি.","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏رَجُلٍ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏يُقَالُ لَهُ ‏ ‏طَلْحَةُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قُلْتُ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏إِنَّ لِي جَارَيْنِ إِلَى أَيِّهِمَا أُهْدِي قَالَ إِلَى أَقْرَبِهِمَا بَابًا مِنْكِ ‏","","",""],[24361,24361,"","ঈশ্বরের কাছে প্রার্থনা করা এক কুঠরীর পুত্র, যে ঈশ্বরের কাছে প্রার্থনা করেছিল, সে তার জীবন ধ্বংস করতে পেরেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏زُهَيْرٍ ‏ ‏عَنْ ‏ ‏عَمْرٍو يَعْنِي ابْنَ أَبِي عَمْرٍو ‏ ‏وَمَوْلَى ‏ ‏الْمُطَّلِبِ ‏ ‏عَنِ ‏ ‏الْمُطَّلِبِ يَعْنِي ابْنَ حَنْطَبٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ الرَّجُلَ لَيُدْرِكُ بِحُسْنِ خُلُقِهِ دَرَجَةَ الصَّائِمِ الْقَائِمِ ‏","","",""],[24362,24362,"","আমরা বিয়ের দুই বছরের সেরাটা নিয়ে কথা বলেছিলাম যেটা খোদা যা ছেড়েছেন, সে একটা অভিশাপ দেবে আর তাদেরকে অন্ধকারে ফেলে দেবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَاصِمٍ ‏ ‏عَنْ ‏ ‏زِرٍّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا تَرَكَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دِينَارًا وَلَا دِرْهَمًا وَلَا شَاةً وَلَا بَعِيرًا ‏ ‏قَالَ ‏ ‏سُفْيَانُ ‏ ‏عُلِمْنَ وَأَشُكُّ فِي الْعَبْدِ وَالْأَمَةِ ‏","","",""],[24363,24363,"","আমরা দুজন সাক্ষীর কথা বলছি, যে বলল, ঈশ্বরের কাছে প্রার্থনা করে আমি তার কাছে প্রার্থনা করি। নতুন করে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏زُبَيْدٍ ‏ ‏عَنْ ‏ ‏مُجَاهِدٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا زَالَ ‏ ‏جِبْرِيلُ ‏ ‏يُوصِينِي بِالْجَارِ حَتَّى ظَنَنْتُ أَنَّهُ مُوَرِّثُهُ ‏","","",""],[24364,24364,"","আমি ঈশ্বরের কাছে প্রার্থনা করেছিলাম যেন তিনি তিনটে ছোটো বিষয় পর শেষ লড়াই করার জন্য তাঁর কাছে ফিরে আসেন । পঞ্চম জনের বলা কথাগুলো বলার পর আমি যে ক্ষুধার কথা বলেছি, তা আমাকে বলা হয়েছে । ঈশ্বর জয়ী হয়েছেন এবং তা করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ عَابِسٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقُلْتُ لَهَا أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْهَى عَنْ لُحُومِ الْأَضَاحِيِّ بَعْدَ ثَلَاثٍ فَقَالَتْ نَعَمْ أَصَابَ النَّاسَ شِدَّةٌ فَأَحَبَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يُطْعِمَ الْغَنِيُّ الْفَقِيرَ ثُمَّ لَقَدْ رَأَيْتُ آلَ ‏ ‏مُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَأْكُلُونَ ‏ ‏الْكُرَاعَ ‏ ‏بَعْدَ خَمْسَ عَشْرَةَ فَقُلْتُ لَهَا مِمَّ ذَاكَ قَالَ فَضَحِكَتْ وَقَالَتْ مَا شَبِعَ آلُ ‏ ‏مُحَمَّدٍ ‏ ‏مِنْ خُبْزٍ ‏ ‏مَأْدُومٍ ‏ ‏ثَلَاثَةَ أَيَّامٍ حَتَّى لَحِقَ اللَّهَ عَزَّ وَجَلَّ ‏","","",""],[24365,24365,"","আমরা আমার প্রতিভার সবচেয়ে ভালো দিক নিয়ে কথা বলেছি, আমরা বলছি কিভাবে আমাকে ভালবাসতে হয়। তোমার মায়ের নাম যেন তার মায়ের বলা হয়, যে সে বলেছে, সে ঈশ্বরেরই সে। পিট, কিংবা বিল্ডিং তোমাকে স্পর্শ না করে রাখে... ...সে যখন জলবায়ু মুক্ত হয় তখন না.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِسْرَائِيلُ ‏ ‏وَزَيْدُ بْنُ الْحُبَابِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏إِسْرَائِيلُ ‏ ‏الْمَعْنَى ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏يُوسُفَ بْنِ مَاهَكَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَلَا نَبْنِي لَكَ ‏ ‏بِمِنًى ‏ ‏بَيْتًا أَوْ بِنَاءً يُظِلُّكَ مِنْ الشَّمْسِ فَقَالَ لَا إِنَّمَا هُوَ ‏ ‏مُنَاخُ ‏ ‏مَنْ ‏ ‏سَبَقَ إِلَيْهِ ‏","","",""],[24366,24366,"","আমরা আমার ছেলেদের সব থেকে ভালো কথা বলেছি যে ছেলে জিতবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏أَبِي عِمْرَانَ الْجَوْنِيِّ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ بَابَنُوسَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَشَّحُنِي وَيَنَالُ مِنْ رَأْسِي وَأَنَا حَائِضٌ ‏","","",""],[24367,24367,"","আমরা আমার মেধার সবচেয়ে ভালো দিক নিয়ে কথা বলেছি, আমরা করুণা খোঁজার কথা বলেছিলাম, আমরা ঈশ্বরের বার্তাবাহকের সাথে ছিলাম এবং আমরা তা পরিষ্কার করার চেষ্টা করছিলাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏لَيْثٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْقَاسِمِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنَّا مَعَ رَسُولِ اللَّهِ ‏ ‏وَكَانَتْ إِحْدَانَا تَحِيضُ وَتَطْهُرُ فَلَا يَأْمُرُنَا بِقَضَاءٍ وَلَا ‏ ‏نَقْضِيهِ ‏","","",""],[24368,24368,"","আমরা আমার বাবার সবচেয়ে ভালটা নিয়ে কথা বলেছিলাম, যার মধ্যে ছিল তার স্মৃতি । কিন্তু এটা আমার কাছে এসে পৌছে যায় এবং জল ও তারপর প্রার্থনা করে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ سَعْدٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏وَأَبُو كَامِلٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏ابْنُ شِهَابٍ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏جَاءَتْ ‏ ‏أُمُّ حَبِيبَةَ بِنْتُ جَحْشٍ ‏ ‏قَالَ ‏ ‏أَبُو كَامِلٍ ‏ ‏أُمُّ حَبِيبٍ ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَتْ ‏ ‏اسْتُحِيضَتْ ‏ ‏سَبْعَ سِنِينَ فَاشْتَكَتْ ذَلِكَ إِلَيْهِ وَاسْتَفْتَتْهُ فِيهِ فَقَالَ لَيْسَ هَذَا بِالْحَيْضَةِ وَلَكِنَّ هَذَا ‏ ‏عِرْقٌ ‏ ‏فَاغْتَسِلِي وَصَلِّي فَكَانَتْ تَغْتَسِلُ لِكُلِّ صَلَاةٍ وَتُصَلِّي وَكَانَتْ تَجْلِسُ فِي ‏ ‏مِرْكَنٍ ‏ ‏فَتَعْلُو حُمْرَةُ الدَّمِ الْمَاءَ ثُمَّ تُصَلِّي ‏","","",""],[24369,24369,"","আমরা আমার ভাইকে তার ভালোবাসার জন্য সবচেয়ে বিখ্যাত খুঁজে পেয়েছি। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার সমস্ত জামার স্বাদের জন্য তাকে ধন্যবাদ জানাতে প্রস্তুত। তারপর আপনি যখন বলেছিলেন তখন আমি তাকে জিজ্ঞেস করলাম যে, আমি তাকে জিজ্ঞেস করলাম যে, আমার ভাইয়ের জন্য সবচেয়ে বিখ্যাত ভাইকে খুঁজে পাওয়া যাবে। ( ১ রাজা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَشْعَثَ بْنِ أَبِي الشَّعْثَاءِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏ ‏التَّيَمُّنُ ‏ ‏فِي شَأْنِهِ كُلِّهِ فِي ‏ ‏تَرَجُّلِهِ ‏ ‏وَفِي طُهُورِهِ وَفِي نَعْلِهِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏ثُمَّ سَأَلْتُهُ بَعْدَ ذَلِكَ فَقَالَ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ ‏ ‏أَوْ يُعْجِبُهُ ‏ ‏التَّيَمُّنُ ‏ ‏مَا اسْتَطَاعَ ‏","","",""],[24370,24370,"","আমার ভাইয়ের জীবনের সেরাটা নিয়ে কথা বলেছি, যে দুই লোক তার চোখের সামনে দিয়ে যায়, পাখি কখনো তাদের নিজের ঘরে ফেলে যায়নি, তাই সে তাদের ছেড়ে দিয়েছে। মারা গেলে হয়ত আমরা তাকে ছেড়ে দিতে পারতাম।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ يَعْنِي ابْنَ صَالِحٍ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ الرَّكْعَتَيْنِ بَعْدَ الْعَصْرِ فَقَالَتْ كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي رَكْعَتَيْنِ بَعْدَ الظُّهْرِ فَشُغِلَ عَنْهُمَا حَتَّى صَلَّى الْعَصْرَ فَلَمَّا فَرَغَ رَكَعَهُمَا فِي بَيْتِي فَمَا تَرَكَهُمَا حَتَّى مَاتَ ‏ ‏قَالَ ‏ ‏عَبْدُ اللَّهِ بْنُ أَبِي قَيْسٍ ‏ ‏فَسَأَلْتُ ‏ ‏أَبَا هُرَيْرَةَ ‏ ‏عَنْهُ قَالَ ‏ ‏قَدْ كُنَّا نَفْعَلُهُ ثُمَّ تَرَكْنَاهُ ‏","","",""],[24371,24371,"","আমরা আমার শ্যালকের ব্যাপারে কথা বলেছি, কিন্তু সে আমার শ্যালকের ব্যাপারে কথা বলেছে। আমি বলেছিলাম তুমি কি রাজপরিবারের কথা পড়ো, আমি বলেছি যে আমরা বলেছি তুমি এটা পরিবর্তন করে ফেলবে এবং তুমি খুঁজে পাবে। এটা তার আত্মার আগুন থেকে এবং তাকে ঈশ্বরের অনুগ্রহের জন্য প্রার্থনা করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏مُعَاوِيَةُ ‏ ‏عَنْ ‏ ‏أَبِي الزَّاهِرِيَّةِ ‏ ‏عَنْ ‏ ‏جُبَيْرِ بْنِ نُفَيْرٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَقَالَتْ هَلْ تَقْرَأُ سُورَةَ ‏ ‏الْمَائِدَةِ ‏ ‏قَالَ قُلْتُ نَعَمْ قَالَتْ فَإِنَّهَا آخِرُ سُورَةٍ نَزَلَتْ فَمَا وَجَدْتُمْ فِيهَا مِنْ حَلَالٍ فَاسْتَحِلُّوهُ وَمَا وَجَدْتُمْ فِيهَا مِنْ حَرَامٍ فَحَرِّمُوهُ ‏ ‏وَسَأَلْتُهَا عَنْ خُلُقِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ الْقُرْآنُ ‏","","",""],[24372,24372,"","আমরা আমার বাবার প্রতি ঈশ্বরের প্রেম নিয়ে কথা বলেছি, কারণ তিনি প্রেমের বিষয়ে শুনেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ أَبِي قَيْسٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ ‏ ‏أَحَبُّ الشُّهُورِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَصُومَهُ شَعْبَانَ ثُمَّ يَصِلَهُ بِرَمَضَانَ ‏","","",""],[24373,24373,"","আমরা আমার প্রতিভাবান পুত্রদের সবচেয়ে ভালো কথা বলেছি যে আমাকে মারতে চেষ্টা করেছিল... ...আমার বাবার সিংহাসনের হাতে শাস্তি পেতে। সে বলল, ঈশ্বর তার জন্য প্রার্থনা করুক, আর তার জীবনে নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏يَعْقُوبُ بْنُ مُحَمَّدٍ ‏ ‏عَنْ ‏ ‏أَبِي الرِّجَالِ ‏ ‏عَنْ ‏ ‏عَمْرَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا ‏ ‏عَائِشَةُ ‏ ‏بَيْتٌ لَيْسَ فِيهِ تَمْرٌ جِيَاعٌ أَهْلُهُ ‏","","",""],[24374,24374,"","আমরা আমাদের বাবার অর্থহীন শান্তির কথা বলেছিলাম, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তাদের বলবে যে তারা আমাকে সবচেয়ে ভালো বানিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَبِي عُثْمَانَ النَّهْدِيِّ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ اجْعَلْنِي مِنْ الَّذِينَ إِذَا أَحْسَنُوا اسْتَبْشَرُوا وَإِذَا أَسَاءُوا اسْتَغْفَرُوا ‏","","",""],[24375,24375,"","আমরা এক গ্রীষ্মের সময় একটা কুঠরীর ছেলেকে নিয়ে কথা বলেছিলাম । তার পাঁচ জন আর সে হেঁটে হেঁটে চলে গেছে। আল্লাহ বলে, আমাদের যে মজা করতে হবে, আমাকে বলো। তারপর তুমি পরিষ্কার হয়ে যাবে। তারপর রান্না আর রান্নার ব্যবস্থা করতে পারবে। তারপর তুমি যাবে, তারপর পানি থেকে একটা নীরব নাচ নিয়ে যাবে। সে বলতে চায় যে, সে যেকোনো সহজাত প্রবৃত্তি বা বিচারকে ক্ষমা করে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ بْنِ مُهَاجِرٍ ‏ ‏عَنْ ‏ ‏صَفِيَّةَ بِنْتِ شَيْبَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏ذُكِرَتْ نِسَاءُ ‏ ‏الْأَنْصَارِ ‏ ‏فَأَثْنَتْ عَلَيْهِنَّ وَقَالَتْ لَهُنَّ مَعْرُوفًا وَقَالَتْ لَمَّا نَزَلَتْ سُورَةُ ‏ ‏النُّورِ ‏ ‏عَمَدْنَ إِلَى ‏ ‏حُجَزِ ‏ ‏أَوْ ‏ ‏حُجُوزِ ‏ ‏مَنَاطِقِهِنَّ فَشَقَقْنَهُ ثُمَّ اتَّخَذْنَ مِنْهُ ‏ ‏خُمُرًا ‏ ‏وَأَنَّهَا دَخَلَتْ ‏ ‏امْرَأَةٌ ‏ ‏مِنْهُنَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنْ الطُّهُورِ مِنْ الْمَحِيضِ فَقَالَ نَعَمْ ‏ ‏لِتَأْخُذْ إِحْدَاكُنَّ مَاءَهَا ‏ ‏وَسِدْرَتَهَا ‏ ‏فَلْتَطَّهَّرْ ثُمَّ لِتُحْسِنْ الطُّهُورَ ثُمَّ تَصُبَّ عَلَى رَأْسِهَا ثُمَّ ‏ ‏لِتُلْزِقْ ‏ ‏بِشُؤُونِ رَأْسِهَا ثُمَّ تَدْلُكْهُ فَإِنَّ ذَلِكَ طُهُورٌ ثُمَّ تَصُبَّ عَلَيْهَا مِنْ الْمَاءِ ثُمَّ تَأْخُذْ ‏ ‏فِرْصَةً ‏ ‏مُمَسَّكَةً ‏ ‏فَلْتَطَّهَّرْ بِهَا قَالَتْ يَا رَسُولَ اللَّهِ كَيْفَ أَتَطَهَّرُ بِهَا فَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْنِي عَنْ ذَلِكَ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏تَتْبَعُ بِهَا أَثَرَ الدَّمِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏ثُمَّ لِتَصُبَّ عَلَى رَأْسِهَا مِنْ الْمَاءِ وَلْتُلْصِقْ شُؤُونَ رَأْسِهَا فَلْتَدْلُكْهُ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏إِلَى ‏ ‏حُجَزٍ ‏ ‏أَوْ ‏ ‏حُجُوزٍ ‏","","",""],[24376,24376,"","মাহিদীর সবচেয়ে ভালোটা নিয়ে আমরা কথা বলেছি। আমার মা আর চাচার সাথে এটা করেছি। বলা হয়, বাসাটা ঈশ্বরের কাছে প্রার্থনা করছিল, তাঁর পতাকা আর আলো যেন পাওয়া যায়।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏زَائِدَةُ ‏ ‏عَنْ ‏ ‏صَدَقَةَ ‏ ‏رَجُلٍ مِنْ أَهْلِ ‏ ‏الْكُوفَةِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏جُمَيْعُ بْنُ عُمَيْرٍ ‏ ‏أَحَدُ ‏ ‏بَنِي تَيْمِ اللَّهِ ابْنِ ثَعْلَبَةَ ‏ ‏قَالَ ‏ ‏دَخَلْتُ مَعَ أُمِّي وَخَالَتِي عَلَى ‏ ‏عَائِشَةَ ‏ ‏فَسَأَلَتْ إِحْدَاهُمَا كَيْفَ كُنْتُنَّ تَصْنَعْنَ عِنْدَ الْغُسْلِ فَقَالَتْ ‏ ‏عَائِشَةُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَتَوَضَّأُ وُضُوءَهُ لِلصَّلَاةِ ثُمَّ يُفِيضُ عَلَى رَأْسِهِ ثَلَاثَ مَرَّاتٍ وَنَحْنُ نُفِيضُ عَلَى رُءُوسِنَا خَمْسًا مِنْ أَجْلِ ‏ ‏الضَّفْرِ ‏","","",""],[24377,24377,"","আমরা মাহদির জীবনের দুই বার জীবনের সেরাতম কথা বলেছি, ঈশ্বরের উত্তর দেয়া হয়েছে... ...আর যদি সে আপনার ক্ষমতা নিয়ে ঘরে আসে তাহলে সে আত্মসমর্পণ করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا دَخَلَ بَيْتَهُ بَدَأَ بِالسِّوَاكِ ‏","","",""],[24378,24378,"","ঈশ্বর তার সঙ্গে যে - শান্তি রয়েছে, তা তিনি অনুভব করেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ شَيْبَانَ ‏ ‏عَنْ ‏ ‏أَبِي نَوْفَلٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُتَسَامَعُ عِنْدَهُ الشِّعْرُ فَقَالَتْ قَدْ كَانَ أَبْغَضَ الْحَدِيثِ إِلَيْهِ ‏","","",""],[24379,24379,"","সে একটা জীবন সম্বন্ধে বলছিল, যাতে সে তোমার কাছ থেকে শুনতে পারে।","‏ ‏وَقَالَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏ ‏الْجَوَامِعُ ‏ ‏مِنْ الدُّعَاءِ وَيَدَعُ مَا بَيْنَ ذَلِكَ ‏","","",""],[24380,24380,"","আমি আমার বাবার সবচেয়ে ভালটা নিয়ে কথা বলেছিলাম । আমার বিশ্বাস, আমার ছেলে বার লুকিয়ে আছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ زَيْدٍ ‏ ‏عَنْ ‏ ‏مَرْوَانَ أَبِي لُبَابَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَائِشَةَ ‏ ‏تَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَصُومُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يُفْطِرَ وَيُفْطِرُ حَتَّى نَقُولَ مَا يُرِيدُ أَنْ يَصُومَ وَكَانَ يَقْرَأُ كُلَّ لَيْلَةٍ ‏ ‏بِبَنِي إِسْرَائِيلَ ‏ ‏وَالزُّمَرِ ‏","","",""],[24381,24381,"","আমার ভাইয়ের জন্য আমার নিজের উপহারের কথা বলেছিলাম, ঈশ্বর বেনকে আমার কাছে দিতে চান। আমি সিদ্ধান্ত নিতে যাচ্ছি যে, তিনি ফাহার হতে চান কিনা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏مَالِكٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏عُرْوَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا خُيِّرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ أَمْرَيْنِ قَطُّ إِلَّا ‏ ‏اخْتَارَ أَيْسَرَهُمَا إِلَّا أَنْ يَكُونَ فِيهِ إِثْمٌ فَإِنْ كَانَ إِثْمًا كَانَ أَبْعَدَ النَّاسِ مِنْهُ ‏","","",""],[24382,24382,"","রাজা আমার বয়স বা আমার বাবা আমরা যা করেছি তার উপর আমরা কথা বলেছি। তার নামই যে নবী তাঁর কাছে এসেছেন এবং তিনি এ সম্পর্কে বলেছেন। বছরের পর মাস ধরে সে এই বিষয়ে সব কিছু বলতে চেয়েছিল, সে সারা পৃথিবী থেকে এটা নিতে চেয়েছিল যা করতে পারবে না, তা না করেও... ...যদি ঈশ্বর তা না করতেন, তাহলে সে করতে পারত না। ( পড়ুন, গীতসংহিতা ৫৫: ২২.)","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو أَبُو عَامِرٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏أَنَّ ‏ ‏عَائِشَةَ ‏ ‏حَدَّثَتْهُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَكُنْ يَصُومُ مِنْ شَهْرٍ مِنْ السَّنَةِ أَكْثَرَ مِنْ صَوْمِهِ مِنْ شَعْبَانَ فَإِنَّهُ كَانَ يَصُومُ شَعْبَانَ كُلَّهُ وَكَانَ يَقُولُ ‏ ‏خُذُوا مِنْ الْعَمَلِ مَا تُطِيقُونَ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ لَا ‏ ‏يَمَلُّ ‏ ‏حَتَّى ‏ ‏تَمَلُّوا ‏ ‏وَإِنَّهُ كَانَ أَحَبُّ الصَّلَاةِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا دُووِمَ عَلَيْهَا وَكَانَ إِذَا صَلَّى صَلَاةً دَاوَمَ عَلَيْهَا ‏","","",""],[24383,24383,"","আমি আমার বাবার স্বপ্নের কথা বলেছিলাম এবং আমি বেঁচে থাকার ভয় পাচ্ছি। ঈশ্বরের দয়া তার কাছে প্রার্থনা করেছে এবং তিনি বললেন, তিনি তিনটির জন্য প্রার্থনা করছেন। তাহলে একটা চ্যাম্পিয়নের জন্য প্রার্থনা করো, তারপর সে দুই নাম্বারটা ফেরত চায় আর সে একটা গাগাথার ছেলে যদি চলে যায় তাহলে সে ঈশ্বরের কাছে প্রার্থনা করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏وَيَزِيدُ ‏ ‏قَالَا أَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏عَنْ صَلَاةِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّيْلَ قَالَتْ كَانَ ‏ ‏يُصَلِّي ثَلَاثَ عَشْرَةَ رَكْعَةً ‏ ‏يُصَلِّي ‏ ‏ثَمَانِيَ رَكَعَاتٍ ثُمَّ ‏ ‏يُوتِرُ ‏ ‏ثُمَّ ‏ ‏يُصَلِّي رَكْعَتَيْنِ وَهُوَ جَالِسٌ فَإِذَا أَرَادَ أَنْ يَرْكَعَ قَامَ فَرَكَعَ ثُمَّ ‏ ‏يُصَلِّي الرَّكْعَتَيْنِ بَيْنَ النِّدَاءِ وَالْإِقَامَةِ مِنْ صَلَاةِ الصُّبْحِ ‏","","",""],[24384,24384,"","আমরা আমার ভালবাসার কথা দুটি শোনার ভাল দিক নিয়ে কথা বলেছি। ঈশ্বর তাঁর জীবন নিয়ে কথা বলছেন। তিনি বলছেন, আমার প্রভু শান্তি ও শান্তির জন্য প্রার্থনা করেছেন। এটা আমার জীবনের সবচেয়ে ভালো দিক। আমি আপনাদের বলছি, আমি কি জানি? আমি জানি, আমি কি বলছি, আমি জানি, আমি কি বলছি, আমি জানি, আমি কি বলছি, আমি কি বলছি, আমি জানি না, আমি কি বলছি, আমি জানি না, আমি কি বলছি, আমি সত্যিই বলছি, তিনি বলেছিলেন, যদি এটা হ্রদে পানি থাকে, তা হলে আপনি প্রত্যেকটা শব্দই বিয়ে করেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سُفْيَانَ ‏ ‏يُحَدِّثُ قَالَ حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ الْأَقْمَرِ ‏ ‏عَنْ ‏ ‏أَبِي حُذَيْفَةَ ‏ ‏وَكَانَ مِنْ أَصْحَابِ ‏ ‏عَبْدِ اللَّهِ ‏ ‏وَكَانَ ‏ ‏طَلْحَةُ ‏ ‏يُحَدِّثُ عَنْهُ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏حَكَيْتُ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا فَقَالَ ‏ ‏مَا يَسُرُّنِي أَنِّي حَكَيْتُ رَجُلًا وَأَنَّ لِي كَذَا وَكَذَا قَالَتْ فَقُلْتُ يَا رَسُولَ اللَّهِ إِنَّ ‏ ‏صَفِيَّةَ ‏ ‏امْرَأَةٌ وَقَالَ بِيَدِهِ كَأَنَّهُ ‏ ‏يَعْنِي قَصِيرَةً فَقَالَ لَقَدْ مَزَجْتِ بِكَلِمَةٍ لَوْ مُزِجَ بِهَا مَاءُ الْبَحْرِ مَزَجَتْ ‏","","",""],[24385,24385,"","সে বলেছে যে আমি এটা আমার বাবাকে লিখতে দেখেছি, সে ঈশ্বরের মৃত্যু শুনতে পায়নি, দুই বছর ধরে এক ভয়ংকর ছেলের প্রতি করুণা প্রদর্শন করেছি। খোদা তার ইচ্ছার কথা বলে দেবে যদি সে মুখ থেকে বের হয়।","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ هَذَا الْحَدِيثَ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏لَمْ يَسْمَعْ ‏ ‏عَبْدُ اللَّهِ ‏ ‏هَذَا الْحَدِيثَ ‏ ‏يَعْنِي حَدِيثَ ‏ ‏جَابِرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏جَابِرٍ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏إِذَا خَرَجَ مِنْ ‏ ‏الْخَلَاءِ ‏ ‏تَوَضَّأَ ‏","","",""],[24386,24386,"","আমরা আমাদের সবচেয়ে ভালো কিছুর কথা বলেছি, ঈশ্বরের দোহাই... ...আর তিনি আমাকে দিয়েছেন... ...যখন তিনি বলেছিলেন, এটা করা হয়নি...","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏عَلْقَمَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخُصُّ مِنْ الْأَيَّامِ شَيْئًا قَالَتْ ‏ ‏لَا كَانَ عَمَلُهُ ‏ ‏دِيمَةً ‏ ‏وَأَيُّكُمْ كَانَ يُطِيقُ مَا كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُطِيقُ ‏","","",""],[24387,24387,"","আমি আমাদের কাছে অনুরোধ করেছিলাম যেন আমরা একটা মাত্রর পর একটা মাত্রর মধ্যে থেকে শেষ পর্যন্ত একটা করে শেষ পর্যন্ত আমি তাকে বলি । আর ঈশ্বর কে রক্ষা করা হয়েছে, আমি পরিষ্কার করে ফেলেছি আর আমি গর্ভবতী।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا حِضْتُ يَأْمُرُنِي ‏ ‏فَأَتَّزِرُ ‏ ‏ثُمَّ ‏ ‏يُبَاشِرُنِي ‏ ‏وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَغْتَسِلُ أَنَا وَهُوَ مِنْ إِنَاءٍ وَاحِدٍ وَنَحْنُ جُنُبَانِ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُخْرِجُ رَأْسَهُ إِلَيَّ وَهُوَ ‏ ‏مُعْتَكِفٌ ‏ ‏فَأَغْسِلُهُ وَأَنَا حَائِضٌ ‏","","",""],[24388,24388,"","আমি বলেছি, আমি নির্দোষ, আমি বিয়ার কিনছি আর আমি সমস্যা নেই।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا ‏ ‏اشْتَرَتْ ‏ ‏بَرِيرَةَ ‏ ‏قَالَتْ قُلْتُ يَا رَسُولَ اللَّهِ ‏ ‏أَشْتَرِي ‏ ‏بَرِيرَةَ ‏ ‏وَأَشْتَرِطُ ‏ ‏لَهُمْ ‏ ‏الْوَلَاءَ ‏ ‏قَالَ اشْتَرِي فَإِنَّمَا ‏ ‏الْوَلَاءُ ‏ ‏لِمَنْ وَلِيَ النِّعْمَةَ ‏ ‏أَوْ لِمَنْ أَعْتَقَ ‏","","",""],[24389,24389,"","আমি আমার প্রভু, প্রভু, ঈশ্বর তার জন্য প্রার্থনা এবং তার জীবন সিংহাসনের কাছে রেখে এবং তারপর তিনি হবেন না। ক্ষমা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏وَالْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏هَدْيِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غَنَمًا ثُمَّ لَا يُحْرِمُ ‏","","",""],[24390,24390,"","ঈশ্বর এটা দাবি করেছেন এবং তিনি তৃষ্ণার জন্য তৈরি করেননি । প্রভুর ভালবাসা।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَعْمَشِ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمْ يَصُمْ الْعَشْرَ ‏ ‏قَالَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏وَأَسْنَدَهُ ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏","","",""],[24391,24391,"","আমরা দু'বছরের কথা বলেছি আর আপনি বলেছিলেন আমরা আমার ভাইয়ের দৃষ্টি নিয়ে কথা বলব। ঈশ্বর তোমার সাহায্য করতে পারেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَوَكِيعٌ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏أَبِي الضُّحَى ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَقُولَ فِي سُجُودِهِ وَرُكُوعِهِ ‏ ‏سُبْحَانَكَ رَبَّنَا وَبِحَمْدِكَ اللَّهُمَّ اغْفِرْ لِي ‏ ‏يَتَأَوَّلُ ‏ ‏الْقُرْآنَ ‏ ‏قَالَ ‏ ‏وَكِيعٌ ‏ ‏اللَّهُمَّ وَبِحَمْدِكَ ‏","","",""],[24392,24392,"","আমরা একজন যাজকের চেয়ে দুই বছরের দর্শন আরও ভাল করে আলোচনা করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ عَبْدِ اللَّهِ بْنِ يَزِيدَ ‏ ‏عَنْ ‏ ‏مَوْلًى لِعَائِشَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏مَا رَأَيْتُ فَرْجَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَطُّ ‏","","",""],[24393,24393,"","আমরা প্রভুর দেবতা সম্পর্কে দুই তলোয়ারের সবচেয়ে ভাল কথা বলেছি। - রাজধানী।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَمَّادٍ ‏ ‏عَنْ ‏ ‏إِبْرَاهِيمَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَخْرُجُ إِلَى صَلَاةِ الصُّبْحِ وَرَأْسُهُ يَقْطُرُ فَيُصْبِحُ صَائِمًا ‏","","",""],[24394,24394,"","ঈশ্বর সম্বন্ধে জানার পর থেকে ঈশ্বর যে - মন্দ বিষয়গুলো সম্পাদন করেছেন, সেগুলো থেকে তারা অনেক কিছু শিখতে পেরেছে । ঈশ্বর যদি বলেন,","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْمِقْدَامِ بْنِ شُرَيْحٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا رَأَى ‏ ‏نَاشِئًا ‏ ‏مِنْ أُفُقٍ مِنْ آفَاقِ السَّمَاءِ تَرَكَ عَمَلَهُ وَإِنْ كَانَ فِي صَلَاتِهِ ثُمَّ يَقُولُ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا فِيهِ فَإِنْ كَشَفَهُ اللَّهُ حَمِدَ اللَّهَ وَإِنْ مَطَرَتْ قَالَ اللَّهُمَّ ‏ ‏صَيِّبًا ‏ ‏نَافِعًا ‏","","",""],[24395,24395,"","আমরা দুজন তলোয়ার আর বাপের কথা বলেছিলাম, যে শয়তান সম্পর্কে কথা বলেছিল। তার বাবা তার বাবার কাছে তার নিজের রক্ষককে তুলে আনবে আর সে তার বিশেষ ক্ষমতা উদ্ধার করবে। সকল পাপের শ্রেণী।","‏ ‏حَدَّثَنَا ‏ ‏عبدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الشَّيْبَانِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ الْأَسْوَدِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَخَّصَ فِي ‏ ‏الرُّقْيَةِ ‏ ‏مِنْ كُلِّ ذِي ‏ ‏حُمَةٍ ‏","","",""],[24396,24396,"","আমরা বাবার টাকা ফেরত দেবার কথা বলেছিলাম... ...আমার ভাইয়ের পরিবারের কথা ভুলে গিয়ে, ঈশ্বর তাকে আত্মসমর্পণ করতে বলেছেন প্রত্যেক মাতালকে হত্যা করতে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏مَالِكِ بْنِ أَنَسٍ ‏ ‏عَنِ ‏ ‏الزُّهْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي سَلَمَةَ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏قَالَتْ ‏ ‏سُئِلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ ‏ ‏الْبِتْعِ ‏ ‏فَقَالَ ‏ ‏كُلُّ شَرَابٍ أَسْكَرَ فَهُوَ حَرَامٌ ‏","","",""],[24397,24397,"","আমরা আমাদের মায়ের মুখের কথা বলেছি তার ভালবাসার কথা নিয়ে এক গ্রীষ্মের ছেলের চোখের কথা। বেঁচে আছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏مَنْصُورِ ابْنِ صَفِيَّةَ ‏ ‏عَنْ ‏ ‏أُمِّهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَضَعُ رَأْسَهُ فِي حِجْرِهَا وَيَقْرَأُ الْقُرْآنَ وَهِيَ حَائِضٌ ‏","","",""],[24398,24398,"","বাবার ছেলের কথা শুনে আমরা আমাদের সাহায্য করেছিলাম, যিনি আমাদের বলেছিলেন, আমরা সারাজীবন ধরে এই কথা বলেছি, আমরা সবাই এমন লোক যারা এটা খেলতে চেষ্টা করছে। আমি খুবই খারাপ। আমি তো বলতে চাই, মানুষ বলে। আমি তার হাত থেকে শুনতে পাব যে যুক্তির মুখ থেকে আমি তাকে বাঁচাতে পারব, যখন তার আত্মা কিছু করতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَامِرٌ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏عَائِشَةَ ‏ ‏قَالَ قُلْتُ إِنَّ هَاهُنَا رَجُلًا يَبْعَثُ بِهَدْيِهِ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏فَيَأْمُرُ الَّذِي يَسُوقُهَا لَهُ مِنْ مَعْلَمٍ قَدْ أَمَرَهُ فَيُقَلِّدُهَا وَلَا يَزَالُ مُحْرِمًا حَتَّى يُحِلَّ النَّاسُ قَالَ فَسَمِعْتُ تَصْفِيقَ يَدَيْهَا مِنْ وَرَاءِ الْحِجَابِ ‏ ‏لَقَدْ كُنْتُ ‏ ‏أَفْتِلُ ‏ ‏قَلَائِدَ ‏ ‏الْهَدْيِ ‏ ‏لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَيَبْعَثُ ‏ ‏بِهَدْيِهِ ‏ ‏فَمَا يَحْرُمُ عَلَيْهِ شَيْءٌ مِمَّا يَحْرُمُ عَلَى الرَّجُلِ مِنْ أَهْلِهِ حَتَّى يَرْجِعَ النَّاسُ ‏","","",""],[24399,24399,"","আমরা একজন অপরাধীর ব্যাপারে খুশি হয়েছি যার বেঁচে থাকতে পারবে না, ঈশ্বর দুঃখ প্রকাশ করতে হবে, আর তার জন্য না যেতে দিতে পারবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏هِشَامٍ يَعْنِي ابْنَ عُرْوَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏أَنَّهَا قَالَتْ ‏ ‏إِنَّمَا ‏ ‏نَزَلَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمُحَصَّبَ ‏ ‏لِيَكُونَ أَسْمَحَ لِخُرُوجِهِ وَلَيْسَ بِسُنَّةٍ فَمَنْ شَاءَ نَزَلَهُ وَمَنْ شَاءَ لَمْ يَنْزِلْهُ ‏","","",""],[24400,24400,"","গরুের বিছানা থেকে যা যা আছে, তার অন্য কিছু থেকে তারা তাকে ঈশ্বরের সেবা করতে আদেশ দিয়েছে এবং সূর্যের কাছে আত্মসমর্পণ করেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْصُورٌ ‏ ‏عَنْ ‏ ‏مُسْلِمٍ ‏ ‏عَنْ ‏ ‏مَسْرُوقٍ ‏ ‏عَنْ ‏ ‏عَائِشَةَ ‏ ‏لَمَّا نَزَلَتْ الْآيَاتُ الْأَوَاخِرُ مِنْ سُورَةِ ‏ ‏الْبَقَرَةِ ‏ ‏قَرَأَهُنَّ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى النَّاسِ وَحَرَّمَ ‏ ‏التِّجَارَةَ فِي الْخَمْرِ ‏","","",""]];
